/* Bluehost bot shield answers a first API request with a cookie challenge (409): set the cookie it asks for and retry once */
function apiText(url,opts,retried){return fetch(url,opts).then(r=>r.text().then(txt=>{const ck=!retried&&r.status===409&&txt.match(/document\.cookie\s*=\s*"([^";]+=[^";]*)"/);
 if(ck){document.cookie=ck[1]+"; path=/; SameSite=None; Secure";return apiText(url,opts,true)}return{r,txt}}))}
