/* ---------- logo: five facets around an open core ---------- */
function logoSVG(size,hi){const C=50,R=47,r=17;const pts=rad=>[0,1,2,3,4].map(i=>{const a=(-90+72*i)*Math.PI/180;return[C+rad*Math.cos(a),C+rad*Math.sin(a)]});const O=pts(R),I=pts(r);let out="";
 for(let i=0;i<5;i++){const j=(i+1)%5,q=[O[i],O[j],I[j],I[i]];const cx=q.reduce((a,p)=>a+p[0],0)/4,cy=q.reduce((a,p)=>a+p[1],0)/4;const s=q.map(p=>[(cx+(p[0]-cx)*.9).toFixed(2),(cy+(p[1]-cy)*.9).toFixed(2)].join(",")).join(" ");
  const fill=(hi==null||hi===i)?`var(--f${i+1})`:"var(--f-off)";out+=`<polygon points="${s}" fill="${fill}" stroke="${fill}" stroke-width="2.4" stroke-linejoin="round"/>`}
 return `<svg width="${size}" height="${size}" viewBox="0 0 100 100" aria-hidden="true" focusable="false">${out}</svg>`}
