function totals(items,billing){items=items||state.cart;billing=billing||state.billing;
 const ids=new Set(items.filter(i=>i.kind==="svc"&&i.id!=="lang").map(i=>i.id));const n=ids.size;const rate=n>=4?.2:n===3?.15:n===2?.1:0;
 let setup=0,mo=0,dom=0;items.forEach(i=>{if(i.kind==="svc"){const s=SVC[i.id],q=i.qty||1;setup+=s.setup*q;mo+=s.mo*q}else if(i.kind==="domain")dom+=i.price});
 const promo=(typeof promoOn==='function'&&promoOn())?setup*PROMO.rate:0,setupP=setup-promo,discSetup=setupP*rate,discMo=mo*rate,moNet=mo-discMo,mult=billing==="annual"?10:1,period=moNet*mult;
 return{n,rate,setup,mo,promo,discSetup,discMo,setupNet:setupP-discSetup,moNet,period,mult,dom,due:setupP-discSetup+dom+period}}
const inCart=id=>state.cart.some(i=>i.kind==="svc"&&i.id===id);
