function svcIcon(id,size){return `<span class="sicon" style="width:${size||46}px;height:${size||46}px">${SICON[id]}</span>`}
/* ---------- v5: SR-style mega menus ---------- */
const MM_BADGE={web:"popular",ecom:"popular",geo:"ai",app:"popular",saas:"new_b"};
const RICON={estimator:IC('<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2M12 11h2M16 11h0M8 15h2M12 15h2M8 18h2M12 18h4"/>'),audit:IC('<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4M8 11l2 2 4-4"/>'),assessment:SICON.geo,compare:IC('<rect x="3" y="4" width="7" height="16" rx="1.5"/><rect x="14" y="4" width="7" height="16" rx="1.5"/><path d="M6.5 8v1M17.5 8v1M6.5 12v1M17.5 12v1"/>'),insights:IC('<path d="M4 5a2 2 0 0 1 2-2h12v16H6a2 2 0 0 0-2 2V5Z"/><path d="M8 7h6M8 11h6"/>'),care:SICON.care,partners:IC('<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M2.5 20a5.5 5.5 0 0 1 11 0M14 20a4 4 0 0 1 7.5-2"/>')};
const badgeHTML=k=>k?`<span class="mm-badge ${k}">${k==="ai"?"AI":k==="new_b"?t("new_b"):t("popular")}</span>`:"";
function mmPromo(kind){const svc=kind==="svc";return `<a class="mm-promo" href="${svc?"#/services":"#/estimator"}"><span class="mm-wm">${logoSVG(260)}</span><h3>${t(svc?"mm_promo_h":"mm_res_promo_h")}</h3><p>${t(svc?"mm_promo_p":"mm_res_promo_p")}</p>
 <div class="mm-mock">${svc?`<div class="mmk-bar"><i></i><i></i><i></i></div><div class="mmk-hero"><b></b><b></b><span></span></div><div class="mmk-cards"><i></i><i></i><i></i></div>`:`<div class="mmk-est"><small>${t("est_res")}</small><b>${money(3200)} – ${money(4400)}</b><div class="mmk-sl"><i></i></div><div class="mmk-sl s2"><i></i></div></div>`}</div>
 <span class="btn btn-accent btn-sm">${svc?t("order_now"):t("est_h")} ›</span></a>`}
function megaMenu(route,sub){return `<div class="dd mega ${route==="service"||route==="services"?"on":""}" id="ddS"><button data-action="ddS" aria-expanded="false" aria-controls="ddSm">${t("nav_services")}</button><div class="dd-menu mm" id="ddSm"><div class="mm-in">${mmPromo("svc")}
 <div class="mm-cols">${SGROUPS.map(([g,ids])=>`<div class="mm-col"><p class="mm-g">${t(g)}</p>${ids.map(id=>`<a href="#/service/${id}" class="mm-item ${sub===id?"on":""} ${MM_BADGE[id]?"hot":""}"><span class="mm-ico">${SICON[id]}</span><span class="mm-tx"><b>${t("sp_"+id)}${badgeHTML(MM_BADGE[id])}</b><small>${spx(id).sd}</small></span></a>`).join("")}</div>`).join("")}</div></div>
 <div class="mm-foot"><a href="#/services">${t("all_svc")} ›</a><span>${waBtn("btn-sm")}<a class="btn btn-accent btn-sm" href="#/pricing">${t("order_now")}</a></span></div></div></div>`}
function resMenu(route){const on=RES_LINKS.some(l=>l[0]===route);return `<div class="dd mega ${on?"on":""}" id="dd"><button data-action="dd" aria-expanded="false" aria-controls="ddm">${t("nav_resources")}</button><div class="dd-menu mm mm-res" id="ddm"><div class="mm-in">${mmPromo("res")}
 <div class="mm-cols mm-cols2"><div class="mm-col"><p class="mm-g">${t("tools_h")}</p>${RES_LINKS.slice(0,3).map(([r,h,p])=>`<a href="#/${r}" class="mm-item ${route===r?"on":""} ${r==="estimator"?"hot":""}"><span class="mm-ico">${RICON[r]}</span><span class="mm-tx"><b>${t(h)}${r==="estimator"?badgeHTML("popular"):r==="assessment"?badgeHTML("ai"):""}</b><small>${t(p)}</small></span></a>`).join("")}</div>
 <div class="mm-col"><p class="mm-g">${t("nav_resources")}</p>${RES_LINKS.slice(3).map(([r,h,p])=>`<a href="#/${r}" class="mm-item ${route===r?"on":""}"><span class="mm-ico">${RICON[r]}</span><span class="mm-tx"><b>${t(h)}</b><small>${t(p)}</small></span></a>`).join("")}</div></div></div></div></div>`}
function pageServices(){return `<section class="hero2 svc-hero"><div class="wrap" style="padding:64px 0 72px"><h1 style="max-width:20ch">${t("nav_services")}</h1><p class="lead" style="max-width:60ch">${t("svc_p")}</p><div class="cta-row"><a class="btn btn-accent btn-lg" href="#/pricing">${t("order_now")}</a>${waBtn("btn-lg")}<a class="btn btn-ghost btn-lg" href="#/contact">${t("quote")}</a></div></div></section>
 <div class="wrap" style="padding:64px 0 90px;display:grid;gap:56px">${SGROUPS.map(([g,ids])=>`<section><h2 class="h2 grp-h">${t(g)}</h2><div class="sgrid">${ids.map(id=>`<a class="scard" href="#/service/${id}">${svcIcon(id,52)}<h3>${t("sp_"+id)}</h3><p>${spx(id).tag}</p><span class="go">${t("explore_svc")} ›</span></a>`).join("")}</div></section>`).join("")}</div>
 ${svcCtaBand()}`}
function svcCtaBand(id){return `<section class="final-g"><div class="wrap final" style="padding:80px 0"><h2>${t("svc_cta_h")}</h2><p>${t("svc_cta_p")}</p><div class="cta-row">${id&&QUOTE_SVC.has(id)?`<a class="btn btn-accent btn-lg" href="#quote" data-action="goquote">${t("req_btn")}</a>`:id?`<button class="btn btn-accent btn-lg" data-action="ordersvc" data-id="${id}">${t("order_now")}</button>`:`<a class="btn btn-accent btn-lg" href="#/pricing">${t("order_now")}</a>`}${waBtn("btn-lg",id?`Hello Penta Services, I'm interested in ${I18N.en["sp_"+id]}.`:"")}<a class="btn btn-ghost btn-lg" href="#/contact" ${id?`data-quote="${SP[id].order}"`:""}>${t("quote")}</a></div></div></section>`}
