/* ---------- v6: promo + rich service pages ---------- */
const PROMO={rate:.2,ends:"2026-12-31"}; /* limited-time offer: 20% off setup fees on all packages */
const PCT=Math.round(PROMO.rate*100);
const promoOn=()=>Date.now()<=new Date(PROMO.ends+"T23:59:59").getTime();
const promoDate=()=>fdate(PROMO.ends+"T12:00:00");
const strike=(v)=>`<s class="was">${money(v)}</s>`;
const ptime=s=>String(s||"").replace("weeks",t("weeks")).replace("Ongoing",t("ongoing")).replace("Start in 48 hours",t("start48"));
