function bigPenta(a){const C=230,R=208,r=80;const P=rad=>[0,1,2,3,4].map(i=>{const g=(-90+72*i)*Math.PI/180;return[C+rad*Math.cos(g),C+rad*Math.sin(g)]});const O=P(R),I=P(r);const base=["#17406D","#1E4A7E","#255690","#2D63A2","#1A4473"];let s="";
 for(let i=0;i<5;i++){const j=(i+1)%5,q=[O[i],O[j],I[j],I[i]];const cx=q.reduce((x,p)=>x+p[0],0)/4,cy=q.reduce((x,p)=>x+p[1],0)/4;const pts=q.map(p=>[(cx+(p[0]-cx)*.93).toFixed(1),(cy+(p[1]-cy)*.93).toFixed(1)].join(",")).join(" ");
  s+=`<g class="fct${i===a?" on":""}" data-action="facet" data-i="${i}" role="button" tabindex="0" aria-pressed="${i===a}" aria-label="${esc(t("p"+(i+1)))}" style="animation-delay:${120+i*110}ms"><polygon points="${pts}" fill="${base[i]}" stroke-linejoin="round"/><text x="${cx.toFixed(1)}" y="${cy.toFixed(1)}" text-anchor="middle" dominant-baseline="central">${esc(t("p"+(i+1)))}</text></g>`}
 const ip=I.map(p=>p.map(v=>v.toFixed(1)).join(",")).join(" ");
 return `<svg class="bigp" viewBox="0 0 460 460" role="group" aria-label="Penta Services: five disciplines">${s}<polygon points="${ip}" fill="none" stroke="rgba(127,214,247,.4)" stroke-dasharray="3 6"/><text class="core" x="${C}" y="${C+4}" text-anchor="middle" dominant-baseline="central">${esc(t("core"))}</text></svg>`}
function facetPanel(i){return `<h3>${t("p"+(i+1))}</h3><p>${t("p"+(i+1)+"d")}</p><div class="fchips">${FACET_SVC[i].map(id=>`<button class="fchip ${inCart(id)?"in":""}" data-action="fadd" data-id="${id}" aria-pressed="${inCart(id)}">${inCart(id)?"✓":"+"} ${t("s_"+id)}</button>`).join("")}</div>`}
