function pkgMini(){return `<div class="pm">${["s_web","s_ecom","pk_dg_n"].map((k,i)=>`<div class="${i===0?"on":""}"><span class="ck">${ICON.check}</span><b>${t(k)}</b><small>${money([SVC.web.setup,SVC.ecom.setup,(SVC.seo.setup+SVC.geo.setup)*.9][i])}</small></div>`).join("")}<div class="pm-tot"><span>${t("discount")}</span><b>−15%</b></div></div>`}
function ctaPair(){return `<div class="ctap"><a class="ctac a" href="#/pricing"><span class="mm-wm">${logoSVG(200)}</span><h3>${t("cta2_h1")}</h3><p>${t("cta2_p1").replace("{p}",money(49))}</p><span class="go">${t("order_now")} ›</span></a><a class="ctac b" href="#/contact"><h3>${t("cta2_h2")}</h3><p>${t("cta2_p2")}</p><span class="go">${t("cta_talk")} ›</span></a></div>`}
