function summaryHTML(withBtn){const T=totals();const ann=state.billing==="annual";
 const items=state.cart.map(i=>i.kind==="svc"?`<li>${t("s_"+i.id)}${i.qty>1?" ×"+i.qty:""}</li>`:`<li style="direction:ltr;text-align:start">${esc(i.name)}</li>`).join("");
 return `<h2>${t("summary")}</h2>${state.cart.length?`<ul class="sitems">${items}</ul>`:`<p class="note">${t("cart_empty")}</p>`}${state.tpl&&state.cart.length?`<div class="tpl-selcart"><small>${t("tpl_sel")}</small><a class="link" href="#/tpl/${state.tpl.ind}#design-${state.tpl.id}"><b>${esc(state.tpl.n)}</b></a>${withBtn==="cart"?`<button class="link" data-action="tplrm">${t("remove")}</button>`:""}</div>`:""}
 <div class="sline"><span>${t("setup_total")}</span><span>${money(T.setup)}</span></div>
 <div class="sline"><span>${ann?t("yearly_total"):t("monthly_total")}</span><span>${money(T.mo*T.mult)}</span></div>
 ${T.promo?`<div class="sline disc"><span>${t("promo_disc")}</span><span>−${money(T.promo)}</span></div>`:""}${T.rate?`<div class="sline disc"><span>${t("discount")} (${Math.round(T.rate*100)}%)</span><span>−${money(T.discSetup+T.discMo*T.mult)}</span></div>`:""}
 ${T.dom?`<div class="sline"><span>${t("domains")} ${t("per_year")}</span><span>${money(T.dom)}</span></div>`:""}
 <div class="sline total"><span>${t("due_today")}</span><span>${money(T.due)}</span></div>
 <div class="sline sub"><span>${t("recurring")}</span><span>${money(T.period)}${ann?t("per_year"):t("per_month")}</span></div>
 <p class="note" style="margin:10px 0 16px">${t("vat_note")}</p>
 ${withBtn==="cart"?`<button class="btn btn-accent btn-lg" style="width:100%" data-action="order" ${state.cart.length?"":"disabled"}>${t("place_order")}</button><p class="note" style="margin-top:12px">${t("order_note")}</p>`:`<a class="btn btn-primary btn-lg" style="width:100%" href="#/cart">${t("go_cart")}</a>`}`}
function billingSeg(){return `<div class="seg" role="group" aria-label="Billing"><button data-action="bill" data-v="monthly" aria-pressed="${state.billing==="monthly"}">${t("bill_m")}</button><button data-action="bill" data-v="annual" aria-pressed="${state.billing==="annual"}">${t("bill_a")}</button></div>`}
function domResHTML(){if(!state.domQ)return"";const q=state.domQ.toLowerCase().replace(/^https?:\/\//,"").replace(/^www\./,"").split(".")[0].replace(/[^a-z0-9-]/g,"").slice(0,40);if(!q)return"";
 return Object.entries(TLD).map(([tld,p])=>{const name=q+tld;const h=[...name].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,7);const taken=q.length<3||h%4===0||["google","amazon","apple","penta","microsoft"].includes(q);const has=state.cart.some(i=>i.kind==="domain"&&i.name===name);
  return `<div class="dom-item"><b>${esc(name)}</b><span>${money(p)}${t("per_year")}</span><span class="tag ${taken?"no":"ok"}">${taken?t("taken"):t("available")}</span><button class="btn btn-ghost btn-sm" data-action="adddom" data-n="${esc(name)}" data-p="${p}" ${taken||has?"disabled":""}>${has?"✓":t("add_domain")}</button></div>`}).join("")}
function pagePricing(){const ann=state.billing==="annual";const lq=(state.cart.find(i=>i.id==="lang")||{}).qty||0;
 const rows=SERVICES.filter(s=>s.id!=="lang"&&!QUOTE_PKG.has(s.id)).map(s=>{const sel=inCart(s.id);return `<div class="svc-row ${sel?"sel":""}" role="button" tabindex="0" aria-pressed="${sel}" data-action="togglesvc" data-id="${s.id}"><span class="ck">${ICON.check}</span><div><h3>${t("s_"+s.id)}</h3><p>${t("s_"+s.id+"_d")}</p>${moIncDetails(s.id)}</div><div class="pr">${s.setup&&promoOn()?`<span class="pp-badge" style="margin-bottom:4px">−${PCT}%</span>`:""}<b>${s.setup?money(promoOn()?s.setup*(1-PROMO.rate):s.setup):"—"}</b>${s.setup&&promoOn()?strike(s.setup):""}${t("setup")}<b style="margin-top:6px">${s.mo?money(s.mo*(ann?10:1)):"—"}</b>${s.mo?(ann?t("per_year"):t("per_month")):""}</div></div>`}).join("");
 const presets=Object.entries(PRESETS).map(([k,ids])=>{const T=totals(ids.map(id=>({kind:"svc",id,qty:1})),state.billing);return `<div class="preset"><h3>${t("pre_"+k)}</h3><ul>${ids.map(id=>`<li>${t("s_"+id)}</li>`).join("")}</ul><span class="save">−${Math.round(T.rate*100)}%</span><span class="note">${money(T.setupNet)}${T.promo?strike(T.setupNet+T.promo*(1-T.rate)):""} ${t("setup")} + ${money(T.period)}${ann?t("per_year"):t("per_month")}</span><button class="btn btn-ghost btn-sm" data-action="preset" data-k="${k}">${t("add_bundle")}</button></div>`}).join("");
 return `<div class="wrap phead"><h1>${t("pricing_h")}</h1><p>${t("pricing_p")}</p>${state.cur==="PKR"?`<p class="note">${t("pk_note")}</p>`:""}${billingSeg()}<p class="note" style="margin-top:12px">${t("bundle_note")} <a class="link" href="#/estimator">${t("est_h")}</a></p></div>
 <div class="wrap pr-grid"><div>
  <div class="rows">${rows}
   <div class="svc-row" style="cursor:default"><span></span><div><h3>${t("s_lang")}</h3><p>${t("s_lang_d")}</p>${moIncDetails("lang")}</div><div class="pr"><b>${money(promoOn()?SVC.lang.setup*(1-PROMO.rate):SVC.lang.setup)}</b>${promoOn()?strike(SVC.lang.setup):""} ${t("setup")} + ${money(SVC.lang.mo*(ann?10:1))}${ann?t("per_year"):t("per_month")}<div class="stepper" style="margin-top:8px"><button data-action="lang" data-d="-1" aria-label="−">−</button><span>${lq}</span><button data-action="lang" data-d="1" aria-label="+">+</button></div></div></div></div>
  <div class="custom-q"><div><h2 class="h2" style="font-size:1.5rem">${t("custom_h")}: ${t("by_proposal")}</h2><p>${t("quote_only_note")}</p>${quoteList()}</div><div>${propSteps()}<a class="btn btn-accent" href="#/proposal">${t("req_btn")}</a></div></div>
  <h2 class="h2" style="font-size:1.5rem">${t("presets_h")}</h2><div class="presets">${presets}</div>
  <h2 class="h2" style="font-size:1.5rem" id="domains">${t("domain_h")}</h2>
  <form class="dom" data-form="dom"><input class="inp" name="q" placeholder="${t("domain_ph")}" value="${esc(state.domQ)}" aria-label="${t("domain_h")}" autocomplete="off" dir="ltr"><button class="btn btn-primary" type="submit">${t("search")}</button></form>
  <div class="dom-res" id="domRes">${domResHTML()}</div><p class="note" style="margin-top:10px">${t("domain_note")}</p>
 </div><aside class="summary" id="sum">${summaryHTML()}</aside></div>`}

/* ---------- CART ---------- */
function pageCart(){
 if(state.lastOrder){const o=state.lastOrder;return `<div class="wrap" style="padding:56px 0 90px"><div class="confirm"><p class="note">${t("order_placed")}</p><span class="oid" dir="ltr">${esc(o.id)}</span><p style="margin-top:14px">${t("order_note")}</p><div class="sline total"><span>${t("due_today")}</span><span>${ml(o.totals.due,o.cur)}</span></div><div class="cta-row"><a class="btn btn-primary" href="#/dashboard/orders">${t("view_orders")}</a><a class="btn btn-ghost" href="#/builder">${t("nav_builder")}</a></div></div></div>`}
 const ann=state.billing==="annual";
 const rows=state.cart.map((i,idx)=>{if(i.kind==="svc"){const s=SVC[i.id],q=i.qty||1;return `<tr><td><b>${t("s_"+i.id)}</b><br><span class="note">${t("s_"+i.id+"_d")}</span>${moIncDetails(i.id)}</td><td>${i.id==="lang"?`<div class="stepper"><button data-action="lang" data-d="-1">−</button><span>${q}</span><button data-action="lang" data-d="1">+</button></div>`:"1"}</td><td class="num">${s.setup?money(s.setup*q):"—"}</td><td class="num">${s.mo?money(s.mo*q*(ann?10:1))+(ann?t("per_year"):t("per_month")):"—"}</td><td class="num"><button class="link" data-action="rm" data-i="${idx}">${t("remove")}</button></td></tr>`}
  return `<tr><td><b dir="ltr">${esc(i.name)}</b><br><span class="note">${t("domains")}</span></td><td>1</td><td class="num">${money(i.price)}${t("per_year")}</td><td class="num">—</td><td class="num"><button class="link" data-action="rm" data-i="${idx}">${t("remove")}</button></td></tr>`}).join("");
 return `<div class="wrap phead"><h1>${t("cart_h")}</h1>${billingSeg()}</div><div class="wrap pr-grid"><div>${state.cart.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t("item")}</th><th>${t("qty")}</th><th class="num">${t("setup_total")}</th><th class="num">${ann?t("yearly_total"):t("monthly_total")}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><p style="margin-top:16px"><a class="link" href="#/pricing">+ ${t("nav_pricing")}</a> &nbsp; <a class="link" href="#/pricing#domains">+ ${t("domain_h")}</a></p>`:`<div class="confirm"><p>${t("cart_empty")}</p><a class="btn btn-primary" href="#/pricing">${t("cta_pricing")}</a></div>`}</div><aside class="summary">${summaryHTML("cart")}</aside></div>`}
function placeOrder(){if(!state.cart.length)return;if(!state.user){openAuth(placeOrder);return}
 const btn=document.querySelector('[data-action="order"]');if(btn)btn.disabled=true;const T=totals(),G=x=>money(x);
 const ack=[...state.cart.map(i=>{if(i.kind==="svc"){const s=SVC[i.id],q=i.qty||1;return[t("s_"+i.id)+(q>1?" ×"+q:""),(s.setup?G(s.setup*q)+" "+t("setup")+" + ":"")+G(s.mo*q)+t("per_month")]}return[i.name,G(i.price)+" "+t("per_year")]}),
  ...(state.tpl?[[t("tpl_sel"),state.tpl.n]]:[]),...(T.promo?[[t("promo_disc"),"−"+G(T.promo)]]:[]),...(T.rate?[[t("discount")+" ("+Math.round(T.rate*100)+"%)","−"+G(T.discSetup+T.discMo*T.mult)]]:[]),[t("due_today"),G(T.due)],[t("recurring"),G(T.moNet)+t("per_month")]];
 api("orders",{tz:(()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone}catch(e){return""}})(),items:state.cart.map(i=>i.kind==="svc"?{kind:"svc",id:i.id,qty:i.qty||1}:{kind:"domain",name:i.name}),billing:state.billing,ack,note:state.tpl?"Ready-site design: "+state.tpl.n+" ("+state.tpl.id+", "+state.tpl.ind+")":""})
  .then(j=>{state.cart=[];state.tpl=null;LS.set("p_tpl",null);state.lastOrder=j.order;ACCT=null;save();render();window.scrollTo(0,0)})
  .catch(e=>{if(btn)btn.disabled=false;if(e.status===401){state.user=null;save();openAuth(placeOrder)}else sendFail()})}

/* ---------- DASHBOARD (database) ---------- */
const PILL={await:"st_await",unpaid:"st_await",paid:"st_paid",active:"st_active",pending:"st_pending",progress:"st_progress",done:"st_done",cancelled:"st_cancelled",void:"st_void",open:"st_open",answered:"st_answered",closed:"st_closed",expired:"st_expired"};
const pill=s=>`<span class="pill ${s}">${t(PILL[s]||s)}</span>`;
const itemsSummary=o=>o.items.map(i=>i.kind==="svc"?t("s_"+i.id)+((i.qty||1)>1?" ×"+i.qty:""):i.name).join(", ");
function pageDashboard(tab){if(!state.user)return gateHTML("nav_dashboard");
 const tabs=["over","orders","subs","domains","inv","drafts","support","profile"];if(!tabs.includes(tab))tab="over";
 const nav=tabs.map(k=>`<a href="#/dashboard/${k}" class="${k===tab?"on":""}">${t(k==="profile"?"x_profile":"d_"+k)}</a>`).join("");
 const shell=body=>`<div class="wrap dash"><nav class="dash-nav" aria-label="${t("nav_dashboard")}">${nav}<a href="${wbAppUrl()}" class="wb-open-nav">${t("nav_wb")} ↗</a><button class="link" style="margin:12px 14px;text-align:start" data-action="signout">${t("sign_out")}</button></nav><section>${body}</section></div>`;
 if(!ACCT){loadAccount().then(()=>rerenderKeepScroll()).catch(()=>rerenderKeepScroll());return shell(`<p class="note" style="padding:40px 0">${t("x_loading")}</p>`)}
 const d=ACCT,now=Date.now(),tbl=(head,rows)=>`<div class="tbl-wrap"><table class="tbl"><thead><tr>${head.map(x=>`<th${x[1]?' class="num"':""}>${x[0]}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div>`,none=`<p class="note">${t("none")}</p>`;
 const ordersTbl=list=>list.length?tbl([[t("order")],[t("date")],[t("item")],[t("amount"),1],[t("status")],["",1]],list.map(o=>`<tr><td dir="ltr"><b>${esc(o.id)}</b></td><td>${fdate(o.date)}</td><td>${esc(itemsSummary(o))}</td><td class="num">${ml(o.totals.due,o.cur)}</td><td>${pill(o.status)}</td><td class="num"><button class="link" data-action="inv" data-id="${esc(o.id)}">${t("view")}</button></td></tr>`).join("")):none;
 let body="";
 if(tab==="over"){const act=d.subs.filter(s=>s.status==="active");const nexts=[...d.subs.filter(s=>s.next&&s.status==="active").map(s=>s.next),...d.domains.filter(x=>x.exp&&x.status==="active").map(x=>x.exp)].sort();
  const spend=act.reduce((a,s)=>a+(s.amount/(RATES[s.cur]||1))/(s.billing==="annual"?12:1),0);
  const soon=[...d.subs.filter(s=>s.next&&s.status==="active").map(s=>({n:t("s_"+s.svc),dt:s.next,a:s.amount,c:s.cur})),...d.domains.filter(x=>x.exp&&x.status==="active").map(x=>({n:x.name,dt:x.exp,a:x.price,c:x.cur}))].filter(x=>new Date(x.dt)-now<32*864e5).sort((a,b)=>a.dt<b.dt?-1:1);
  const openT=d.tickets.filter(x=>x.status!=="closed").length,unpaid=d.orders.filter(o=>o.invoice&&o.invoice.status==="unpaid");
  body=`<h1 style="font-size:2rem">${t("d_welcome")}, ${esc(state.user.name.split(" ")[0])}</h1><p class="note">${esc(state.user.email)} · ${esc(state.user.provider||"Email")}</p>
  <div class="stats"><div class="stat"><small>${t("d_active")}</small><b>${act.length}</b></div><div class="stat"><small>${t("d_next")}</small><b>${nexts[0]?fdate(nexts[0]):"—"}</b></div><div class="stat"><small>${t("d_spend")}</small><b>${money(spend)}</b></div><div class="stat"><small>${t("x_unpaid")}</small><b>${unpaid.length}</b></div><div class="stat"><small>${t("x_open_tickets")}</small><b>${openT}</b></div></div>
  <h2>${t("d_upcoming")}</h2>${soon.length?`<div class="tbl-wrap"><table class="tbl"><tbody>${soon.map(x=>`<tr><td>${esc(x.n)}</td><td>${fdate(x.dt)}</td><td class="num">${ml(x.a,x.c)}</td></tr>`).join("")}</tbody></table></div>`:none}
  <h2 style="margin-top:28px">${t("d_orders")}</h2>${ordersTbl(d.orders.slice(0,5))}
  <div class="cta-row"><a class="btn btn-primary" href="#/builder">${t("new_draft")}</a><a class="btn btn-ghost" href="#/pricing">${t("cta_pricing")}</a></div>`}
 if(tab==="orders")body=`<h1 style="font-size:2rem">${t("d_orders")}</h1>${ordersTbl(d.orders)}`;
 if(tab==="subs")body=`<h1 style="font-size:2rem">${t("d_subs")}</h1>${d.subs.length?tbl([[t("item")],[t("amount"),1],[t("renews")],[t("auto_renew")],[t("status")],["",1]],d.subs.map(s=>`<tr><td><b>${t("s_"+s.svc)}</b>${s.qty>1?" ×"+s.qty:""}</td><td class="num">${ml(s.amount,s.cur)}${s.billing==="annual"?t("per_year"):t("per_month")}</td><td>${s.next?fdate(s.next):"—"}</td><td><label class="switch"><input type="checkbox" data-change="auto" data-kind="subscriptions" data-id="${s.id}" ${s.auto?"checked":""} aria-label="${t("auto_renew")}"><span></span></label></td><td>${pill(s.status)}</td><td class="num">${isWb(s.svc)&&s.status==="active"?`<a class="btn btn-accent btn-sm" href="${wbAppUrl()}" data-testid="wb-open">${t("wb_open")}</a> `:""}${s.status==="active"?`<button class="btn btn-ghost btn-sm" data-action="renew" data-kind="subscriptions" data-id="${s.id}">${t("renew_now")}</button>`:""}</td></tr>`).join("")):none}`;
 if(tab==="domains")body=`<h1 style="font-size:2rem">${t("d_domains")}</h1>${d.domains.length?tbl([[t("item")],[t("expires")],[t("amount"),1],[t("auto_renew")],[t("status")],["",1]],d.domains.map(x=>`<tr><td dir="ltr"><b>${esc(x.name)}</b></td><td>${x.exp?fdate(x.exp):"—"}</td><td class="num">${ml(x.price,x.cur)}${t("per_year")}</td><td><label class="switch"><input type="checkbox" data-change="auto" data-kind="domains" data-id="${x.id}" ${x.auto?"checked":""} aria-label="${t("auto_renew")}"><span></span></label></td><td>${pill(x.status)}</td><td class="num">${x.status==="active"?`<button class="btn btn-ghost btn-sm" data-action="renew" data-kind="domains" data-id="${x.id}">${t("renew_now")}</button>`:""}</td></tr>`).join("")):`${none}<a class="btn btn-primary" href="#/pricing#domains">${t("domain_h")}</a>`}`;
 if(tab==="inv"){const inv=d.orders.filter(o=>o.invoice);body=`<h1 style="font-size:2rem">${t("d_inv")}</h1>${inv.length?tbl([[t("x_invoice")],[t("order")],[t("x_issued")],[t("amount"),1],[t("status")],["",1]],inv.map(o=>`<tr><td dir="ltr"><b>${esc(o.invoice.number)}</b></td><td dir="ltr">${esc(o.id)}</td><td>${fdate(o.invoice.issued)}</td><td class="num">${ml(o.totals.due,o.cur)}</td><td>${pill(o.invoice.status)}</td><td class="num"><button class="link" data-action="inv" data-id="${esc(o.id)}">${t("view")}</button></td></tr>`).join("")):none}`}
 if(tab==="drafts")body=`<h1 style="font-size:2rem">${t("d_drafts")}</h1>${d.drafts.length?`<div class="drafts">${d.drafts.map(x=>{const b=x.b||{},P=PAL[b.palette]||PAL.ocean,ans=b.ans||{};return `<div class="draft"><div class="thumb" style="background:linear-gradient(120deg,${P[0]} 60%,${P[1]})"></div><div class="b"><b>${esc(ans.name||"Untitled")}</b><p class="note" style="margin:4px 0 10px">${ans.ind?t("i_"+ans.ind)+" · ":""}${fdate(x.updated)}</p><button class="btn btn-primary btn-sm" data-action="opendraft" data-id="${x.id}">${t("open")}</button> <button class="link" data-action="deldraft" data-id="${x.id}">${t("remove")}</button></div></div>`}).join("")}</div>`:none}<p style="margin-top:18px"><a class="btn btn-ghost" href="#/builder">${t("new_draft")}</a></p>`;
 if(tab==="support")body=`<h1 style="font-size:2rem">${t("d_support")}</h1><form class="form" data-form="ticket"><label>${t("ticket_subject")}<input class="inp" name="s" required></label><label>${t("ticket_msg")}<textarea class="inp" name="m" required></textarea></label><button class="btn btn-primary" type="submit" style="justify-self:start">${t("send")}</button></form>
  <div class="tickets" style="margin-top:28px">${d.tickets.map(x=>`<details class="tk" ${x.status!=="closed"?"":""}><summary><span dir="ltr"><b>${esc(x.id)}</b></span> <b>${esc(x.subject)}</b> ${pill(x.status)} <span class="note">${fdate(x.updated)}</span></summary>
   <div class="tk-msgs">${x.messages.map(m=>`<div class="tk-msg ${m.from==="admin"?"team":"me"}"><small>${m.from==="admin"?t("x_team"):t("x_you")} · ${fdate(m.date)}</small><p>${esc(m.body).replace(/\n/g,"<br>")}</p></div>`).join("")}</div>
   ${x.status!=="closed"?`<form class="form" data-form="treply" data-id="${esc(x.id)}" style="max-width:none;margin-top:10px"><label>${t("x_reply")}<textarea class="inp" name="m" required></textarea></label><div class="cta-row" style="margin:0"><button class="btn btn-primary btn-sm" type="submit">${t("send")}</button><button type="button" class="btn btn-ghost btn-sm" data-action="tclose" data-id="${esc(x.id)}">${t("x_close_ticket")}</button></div></form>`:""}</details>`).join("")}</div>`;
 if(tab==="profile"){const u=state.user;body=`<h1 style="font-size:2rem">${t("x_profile")}</h1>
  <form class="form" data-form="profile" style="max-width:640px"><p class="ferr" role="alert" hidden></p><div class="two"><label>${t("name")}<input class="inp" name="name" required value="${esc(u.name)}" autocomplete="name"></label><label>${t("org")}<input class="inp" name="org" value="${esc(u.org||"")}" autocomplete="organization"></label></div>
   <div class="two"><label>${t("email")}<input class="inp" value="${esc(u.email)}" disabled dir="ltr"></label><label>${t("x_phone")}<input class="inp" name="phone" value="${esc(u.phone||"")}" type="tel" dir="ltr" autocomplete="tel"></label></div>
   <label>${t("url_opt")}<input class="inp" name="website" value="${esc(u.website||"")}" type="url" dir="ltr" placeholder="https://"></label>
   <div class="two"><label>${t("x_lang_pref")}<select class="inp" name="lang">${LANGS.map(([c,l])=>`<option value="${c}" ${c===(u.lang||state.lang)?"selected":""}>${l}</option>`).join("")}</select></label><label>${t("x_cur_pref")}<select class="inp" name="currency">${Object.keys(RATES).filter(c=>c!=="PKR"||PK_OK||u.currency==="PKR").map(c=>`<option ${c===(u.currency||state.cur)?"selected":""}>${c}</option>`).join("")}</select></label></div>
   <button class="btn btn-primary" type="submit" style="justify-self:start">${t("x_save")}</button></form>
  <h2 style="margin-top:36px">${t("x_pw_h")}</h2>${u.has_password?"":`<p class="note">${t("x_set_pw_note").replace("{p}",esc(u.provider||""))}</p>`}
  <form class="form" data-form="pwchange" style="max-width:640px"><p class="ferr" role="alert" hidden></p>${u.has_password?`<label>${t("x_cur_pw")}<input class="inp" name="cur" type="password" required autocomplete="current-password" dir="ltr"></label>`:""}<div class="two"><label>${t("x_new_pw")}<input class="inp" name="p" type="password" required autocomplete="new-password" dir="ltr"></label><label>${t("pw2")}<input class="inp" name="p2" type="password" required autocomplete="new-password" dir="ltr"></label></div><p class="note" style="margin:0">${t("pw_weak")}</p><button class="btn btn-ghost" type="submit" style="justify-self:start">${t("x_pw_h")}</button></form>`}
 return shell(body)}
function invoiceLines(o){const L=[],m=o.billing==="annual"?10:1;
 o.items.forEach(i=>{const nm=(i.kind==="svc"?t("s_"+i.id):i.name)+((i.qty||1)>1?" ×"+i.qty:"");
  if(i.kind==="svc"){if(i.setup)L.push([nm+", "+t("setup"),i.setup]);if(i.mo)L.push([nm+", "+(m>1?t("yearly_total"):t("monthly_total")),i.mo*m])}
  else if(i.kind==="domain")L.push([i.name+" "+t("per_year"),i.amount]);else L.push([nm,i.amount])});
 const T=o.totals;if(T.promo)L.push([t("promo_disc"),-T.promo]);if(T.bundle)L.push([t("discount")+" ("+Math.round(T.rate*100)+"%)",-T.bundle]);return L}
function invoiceHTML(o){const L=invoiceLines(o),inv=o.invoice||{},u=state.user||{};return `<div style="display:flex;justify-content:space-between;align-items:center;gap:12px">${'<span style="display:flex;gap:10px;align-items:center">'+logoSVG(40)+wordmark()+'</span>'}<span style="text-align:end"><b>${t("pro_forma")}</b><br><span dir="ltr">${esc(inv.number||o.id)}</span><br>${t("x_issued")}: ${fdate(inv.issued||o.date)}${inv.due?`<br>${t("x_due_by")}: ${fdate(inv.due)}`:""}</span></div>
 <p style="margin-top:18px"><small class="note">${t("x_bill_to")}</small><br><b>${esc(u.name||"")}</b>${u.org?`<br>${esc(u.org)}`:""}<br><span dir="ltr">${esc(u.email||"")}</span></p><p class="note">${t("order")}: <span dir="ltr">${esc(o.id)}</span> · ${fdate(o.date)}</p>
 <table class="tbl" style="min-width:0"><thead><tr><th>${t("item")}</th><th class="num">${t("amount")}</th></tr></thead><tbody>${L.map(([a,b])=>`<tr><td>${esc(a)}</td><td class="num">${b<0?"−":""}${ml(Math.abs(b),o.cur)}</td></tr>`).join("")}<tr><td><b>${t("due_today")}</b></td><td class="num"><b>${ml(o.totals.due,o.cur)}</b></td></tr></tbody></table>
 <p class="note" style="margin-top:12px">${pill(inv.status||o.status)} · Penta Services · info@pentaservices.co.uk · ${t("vat_note")}</p>`}

/* ---------- BUILDER ---------- */
const PAL={ocean:["#0E2A47","#00AEEF"],forest:["#133C2F","#3DBE8B"],wine:["#4A1426","#E5A33B"],mono:["#151B26","#D3DAE4"],violet:["#2B1A5E","#FF7A59"]};
const FONTS={sans:['"Instrument Sans",sans-serif','"Instrument Sans",sans-serif'],disp:['"Instrument Sans",sans-serif','"Bricolage Grotesque",sans-serif'],serif:['"Instrument Sans",sans-serif','Georgia,"Times New Roman",serif']};
const STYLE={clean:{pal:"mono",r:6,f:"sans"},bold:{pal:"violet",r:14,f:"disp"},lux:{pal:"wine",r:2,f:"serif"},warm:{pal:"forest",r:18,f:"disp"}};
const SECL={hero:"Hero",services:"Services",about:"About",gallery:"Gallery",testimonials:"Reviews",pricing:"Pricing",faq:"FAQ",contact:"Contact"};
const CTA={leads:"Get a free quote",sales:"Shop now",book:"Book now",trust:"Meet our team"};
const IND={
 law:{h:"Practical legal advice, delivered with clarity",sub:"Trusted advisers for businesses and families. Fixed-fee options and same-week consultations.",svcs:[["Commercial law","Contracts, disputes and company matters handled end to end."],["Employment law","Advice for employers on contracts, HR policies and tribunals."],["Property law","Residential and commercial conveyancing without delays."]],about:"We combine decades of experience with plain-English advice, so you always know where you stand and what happens next."},
 clinic:{h:"Specialist care, when you need it",sub:"Book appointments with experienced clinicians, often within the same week.",svcs:[["Consultations","Specialist assessments with clear treatment plans."],["Diagnostics","On-site tests and fast, explained results."],["Therapies","Physiotherapy and rehabilitation programmes."]],about:"Our multidisciplinary team puts patients first, with modern facilities and care that is easy to access."},
 food:{h:"Fresh seasonal food, made to share",sub:"Reserve a table, order online or plan your private event with us.",svcs:[["Dine in","Seasonal menus and a relaxed atmosphere."],["Order online","Collection and delivery from our kitchen to your door."],["Private events","Celebrations, corporate dinners and catering."]],about:"Local ingredients, open-fire cooking and a team that loves hospitality."},
 retail:{h:"Designed to last. Delivered worldwide.",sub:"Discover our latest collection with free returns and secure checkout.",svcs:[["New arrivals","Fresh pieces every month."],["Best sellers","Customer favourites, always in stock."],["Gift cards","The easy present for any occasion."]],about:"We work with responsible makers to create products you will use for years."},
 realestate:{h:"Find the right property, faster",sub:"Search homes and commercial spaces, book viewings and get expert valuations.",svcs:[["Buy","Curated listings with full details and virtual tours."],["Rent","Verified rentals and smooth tenancy setup."],["Valuations","Free, data-backed property valuations."]],about:"Local market knowledge and honest advice for buyers, sellers, landlords and tenants."},
 tech:{h:"Software that runs your operations",sub:"Automate workflows, connect your tools and see every number in one place.",svcs:[["Automation","Replace manual steps with reliable workflows."],["Analytics","Live dashboards for every team."],["Integrations","Connect CRM, ERP and payments in minutes."]],about:"Built by engineers who have scaled products for teams across the UK, Europe and the Gulf."},
 edu:{h:"Learning that opens doors",sub:"Explore programmes, meet our tutors and apply online in minutes.",svcs:[["Courses","Accredited programmes for every level."],["Online learning","Flexible study from anywhere."],["Admissions","Simple applications and fast decisions."]],about:"We help learners build real skills with experienced teachers and practical, career-focused courses."},
 build:{h:"Built right, on time and on budget",sub:"Commercial and residential construction with transparent project management.",svcs:[["New builds","From planning to handover."],["Renovation","Extensions, fit-outs and refurbishments."],["Engineering","Structural and MEP design services."]],about:"Certified teams, strict safety standards and clear communication at every stage."},
 travel:{h:"Stays and journeys worth remembering",sub:"Book rooms, tours and experiences with the best rates direct.",svcs:[["Rooms & suites","Comfortable stays with thoughtful details."],["Experiences","Curated tours and local adventures."],["Events","Weddings, retreats and meetings."]],about:"Warm hospitality and local expertise for travellers from around the world."},
 beauty:{h:"Look good. Feel even better.",sub:"Book treatments online with experienced therapists and premium products.",svcs:[["Treatments","Facials, skincare and body therapies."],["Hair & beauty","Cuts, colour and styling by experts."],["Wellness","Massage and relaxation rituals."]],about:"A calm space, a skilled team and treatments tailored to you."}};
const freshB=()=>({step:0,gen:false,ans:{name:"",ind:"law",goal:"leads",style:"clean",sections:["hero","services","about","testimonials","contact"],langs:["en"]},palette:"mono",font:"sans",radius:6,device:"desk",edits:{},draftId:null});
let B=LS.get("p_builder",null)||freshB();
const saveB=()=>LS.set("p_builder",B);
function genHTML(){const a=B.ans,I=IND[a.ind]||IND.law,P=PAL[B.palette]||PAL.ocean,F=FONTS[B.font]||FONTS.sans,nm=esc(a.name||"Your Business");
 const E=(k,tag,def)=>`<${tag} data-k="${k}" contenteditable="true" spellcheck="false">${B.edits[k]!=null?esc(B.edits[k]):esc(def)}</${tag}>`;
 const S={
  hero:()=>`<header class="g-nav"><span class="g-logo">${esc((a.name||"Y").trim()[0]||"Y").toUpperCase()}</span><b>${nm}</b><nav><span>Home</span><span>Services</span><span>About</span><span>Contact</span></nav>${a.langs.length>1?`<span class="g-lang">${a.langs.map(l=>l.toUpperCase()).join(" | ")}</span>`:""}</header><section class="g-hero"><div>${E("h1","h1",I.h)}${E("hs","p",I.sub)}<span class="g-btn">${E("cta","span",CTA[a.goal])}</span></div><div class="g-art"></div></section>`,
  services:()=>`<section class="g-sec">${E("sh","h2","What we do")}<div class="g-cards">${I.svcs.map((s,i)=>`<div class="g-card"><i></i>${E("s"+i+"t","h3",s[0])}${E("s"+i+"d","p",s[1])}</div>`).join("")}</div></section>`,
  about:()=>`<section class="g-sec g-alt">${E("ah","h2","About "+(a.name||"us"))}${E("ap","p",I.about)}</section>`,
  gallery:()=>`<section class="g-sec">${E("gh","h2","Gallery")}<div class="g-gal">${"<span></span>".repeat(6)}</div></section>`,
  testimonials:()=>`<section class="g-sec g-alt">${E("th","h2","What clients say")}<p class="g-quote">${E("t1","span","Add a real client review here. Reviews with names and dates build the most trust.")}</p><p class="g-quote">${E("t2","span","A second review, ideally from a different type of customer.")}</p></section>`,
  pricing:()=>`<section class="g-sec">${E("ph","h2","Plans")}<div class="g-tiers">${["Starter","Standard","Premium"].map((x,i)=>`<div>${E("p"+i,"h3",x)}<b>${E("pv"+i,"span",["£49","£99","£199"][i])}</b>${E("pd"+i,"p","Describe what is included.")}</div>`).join("")}</div></section>`,
  faq:()=>`<section class="g-sec g-alt">${E("fh","h2","Questions")}${[0,1,2].map(i=>`${E("fq"+i,"h3",["How do I get started?","What does it cost?","Where are you based?"][i])}${E("fa"+i,"p","Write a short, direct answer customers can act on.")}`).join("")}</section>`,
  contact:()=>`<section class="g-sec">${E("ch","h2","Get in touch")}<div class="g-form"><span></span><span></span><span class="t"></span><span class="g-btn" style="text-align:center">${esc(CTA[a.goal])}</span></div></section><footer class="g-foot">© ${new Date().getFullYear()} ${nm}</footer>`};
 return `<div class="gen" id="genroot" style="--g1:${P[0]};--g2:${P[1]};--gr:${B.radius}px;--gf:${F[0]};--gh:${F[1]}">${a.sections.map(s=>S[s]?S[s]():"").join("")}</div>`}
function pageBuilder(){if(!state.user)return gateHTML("b_h");
 if(B.gen){const allS=Object.keys(SECL).filter(s=>s!=="hero");const order=[...B.ans.sections.filter(s=>s!=="hero"),...allS.filter(s=>!B.ans.sections.includes(s))];
  const W={desk:"100%",tab:"768px",mob:"390px"}[B.device];
  return `<div class="wrap phead" style="padding-bottom:18px"><h1>${t("b_h")}</h1><p>${t("edit_hint")}</p></div>
  <div class="wrap ed"><aside class="ed-side">
   <div><h3>${t("sections")}</h3>${order.map(s=>{const on=B.ans.sections.includes(s);return `<div class="srow"><label><input type="checkbox" data-change="sec" data-s="${s}" ${on?"checked":""}> ${SECL[s]}</label>${on?`<button data-action="mv" data-s="${s}" data-d="-1" aria-label="Move up">↑</button><button data-action="mv" data-s="${s}" data-d="1" aria-label="Move down">↓</button>`:""}</div>`}).join("")}</div>
   <div><h3>${t("theme")}</h3><div class="sw">${Object.entries(PAL).map(([k,p])=>`<button data-action="pal" data-k="${k}" aria-pressed="${B.palette===k}" aria-label="${k}" style="background:linear-gradient(135deg,${p[0]} 50%,${p[1]} 50%)"></button>`).join("")}</div></div>
   <div><h3>${t("font")}</h3><div class="seg">${Object.keys(FONTS).map(k=>`<button data-action="font" data-k="${k}" aria-pressed="${B.font===k}">${k==="sans"?"Sans":k==="disp"?"Display":"Serif"}</button>`).join("")}</div></div>
   <div><h3>${t("bq6")}</h3><p class="note" style="margin:0">${B.ans.langs.map(l=>LANGS.find(x=>x[0]===l)[1]).join(", ")}</p></div>
   <button class="link" data-action="brestart">↺ ${t("new_draft")}</button></aside>
   <div><div class="ed-bar"><div class="seg" role="group" aria-label="Device">${[["desk","Desktop"],["tab","Tablet"],["mob","Mobile"]].map(([k,l])=>`<button data-action="dev" data-k="${k}" aria-pressed="${B.device===k}">${l}</button>`).join("")}</div>
   <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-ghost btn-sm" data-action="bsave">${t("save_draft")}</button><button class="btn btn-accent btn-sm" data-action="bpub">${t("publish")}</button></div></div>
   <div class="pframe ${B.device}" style="width:${W}">${genHTML()}</div></div></div>`}
 const steps=6,s=B.step,a=B.ans;
 const opt=(field,val,label,multi,sub)=>{const on=multi?a[field].includes(val):a[field]===val;return `<button class="opt" data-action="bpick" data-f="${field}" data-v="${val}" data-m="${multi?1:0}" aria-pressed="${on}">${label}${sub?`<small>${sub}</small>`:""}</button>`};
 let q="";
 if(s===0)q=`<h2 class="h2" style="font-size:1.6rem">${t("bq1")}</h2><input class="inp" data-input="bname" value="${esc(a.name)}" placeholder="Olive & Ember" style="margin:16px 0 26px;width:100%">`;
 if(s===1)q=`<h2 class="h2" style="font-size:1.6rem">${t("bq2")}</h2><div class="opts">${INDUSTRIES.map(k=>opt("ind",k,t("i_"+k))).join("")}</div>`;
 if(s===2)q=`<h2 class="h2" style="font-size:1.6rem">${t("bq3")}</h2><div class="opts">${["leads","sales","book","trust"].map(k=>opt("goal",k,t("g_"+k))).join("")}</div>`;
 if(s===3)q=`<h2 class="h2" style="font-size:1.6rem">${t("bq4")}</h2><div class="opts">${Object.keys(STYLE).map(k=>{const p=PAL[STYLE[k].pal];return opt("style",k,`<span style="display:block;height:34px;border-radius:${STYLE[k].r}px;background:linear-gradient(120deg,${p[0]} 60%,${p[1]});margin-bottom:10px"></span>`+t("sty_"+k))}).join("")}</div>`;
 if(s===4)q=`<h2 class="h2" style="font-size:1.6rem">${t("bq5")}</h2><div class="opts">${Object.keys(SECL).filter(x=>x!=="hero").map(k=>opt("sections",k,SECL[k],true)).join("")}</div>`;
 if(s===5)q=`<h2 class="h2" style="font-size:1.6rem">${t("bq6")}</h2><div class="opts">${LANGS.map(([c,l])=>opt("langs",c,l,true)).join("")}</div>`;
 return `<div class="wrap phead" style="text-align:center;max-width:780px"><h1>${t("b_h")}</h1><p style="margin-inline:auto">${t("b_p")}</p></div>
 <div class="wrap"><div class="wiz"><p class="note" style="margin:0">${t("step")} ${s+1} / ${steps}</p><div class="prog"><i style="width:${(s+1)/steps*100}%"></i></div>${q}
 <div class="wiz-foot"><button class="btn btn-ghost" data-action="bstep" data-d="-1" ${s===0?"disabled":""}>${t("back")}</button>${s<steps-1?`<button class="btn btn-primary" data-action="bstep" data-d="1">${t("next")}</button>`:`<button class="btn btn-accent" data-action="bgen">${t("generate")}</button>`}</div></div></div>`}
function saveDraft(silent){const snap=JSON.parse(JSON.stringify(B));return api("drafts",{id:B.draftId||0,b:snap}).then(j=>{B.draftId=j.id;saveB();ACCT=null;if(!silent)toast(t("saved"))}).catch(e=>{if(e.status===401){state.user=null;save();openAuth(()=>saveDraft(silent))}else sendFail()})}

