function pageIndustries(){const L=tx("ind",IND_LIST);
 return `<div class="wrap phead"><h1>${t("nav_industries")}</h1><p>${t("ind_intro")}</p></div><div class="wrap" style="padding-bottom:90px"><div class="tbl-wrap"><table class="tbl" style="min-width:0"><tbody>${L.map(([a,b])=>`<tr><td style="width:38%"><b>${a}</b></td><td style="color:var(--ink-2)">${b}</td></tr>`).join("")}</tbody></table></div><p style="margin-top:24px"><a class="btn btn-primary" href="#/contact">${t("cta_talk")}</a></p></div>`}
