function estCalc(){const e=state.est,[,inc,pp]=EST_BASE[e.type],rf=SVC.web.setup/1490,R=RATES[state.cur]||1;
 let s=SVC[e.type].setup+Math.max(0,e.pages-inc)*pp*rf+(e.langs-1)*SVC.lang.setup+e.feat.reduce((a,f)=>a+FEAT[f][1]*rf,0);s*={tpl:.85,custom:1,premium:1.35}[e.design];if(e.rush)s*=1.2;
 const mo=SVC[e.type].mo+(e.langs-1)*SVC.lang.mo+{none:0,seo:SVC.seo.mo,seogeo:(SVC.seo.mo+SVC.geo.mo)*.9}[e.growth];const r=v=>Math.round(v*R/50)*50/R;const pr=e.promo&&promoOn()?1-PROMO.rate:1;
 return{lo:r(s*.9*pr),hi:r(s*1.15*pr),lo0:r(s*.9),hi0:r(s*1.15),pr:pr<1,mo}}
function estOut(){const c=estCalc();return `<p style="margin:0;color:#A9C2DA;font-weight:600">${t("est_res")}</p>${c.pr?`<span class="pp-badge">${t("promo_badge")} · −${PCT}%</span>`:""}<div class="rng">${money(c.lo)} – ${money(c.hi)}</div>${c.pr?`<p style="margin:0;color:#A9C2DA"><s>${money(c.lo0)} – ${money(c.hi0)}</s> · ${t("promo_until").replace("{d}",promoDate())}</p>`:""}<p class="mo">+ ${money(c.mo)}${t("per_month")}</p>${(()=>{const base=PB_BASE[state.cur]||"GBP",b=(BENCH[base]||{})[state.est.type];return b?`<p style="margin:6px 0 0;color:#A9C2DA;font-size:13.5px">${t("est_bench").replace("{m}",t("mk_"+mktOfCur())).replace("{r}",money(b[0]/RATES[base])+" – "+money(b[1]/RATES[base]))}</p>`:""})()}<p style="margin:4px 0 0;color:#A9C2DA;font-size:12.5px">${t("est_vat")}${state.cur==="PKR"?" "+t("pk_note"):""}</p><p style="color:#A9C2DA;font-size:14px;margin:6px 0 0">${t("trust_2")}</p><div class="stripe" style="margin:20px 0;border-radius:3px"></div><button class="btn btn-accent btn-lg" style="width:100%" data-action="estadd">${t("est_add")}</button><button class="btn btn-ghost btn-lg" style="width:100%;margin-top:10px;color:#fff;border-color:rgba(255,255,255,.3)" data-action="quote" data-s="${state.est.type}">${t("quote")}</button><p style="font-size:13px;color:#A9C2DA;margin:14px 0 0">${t("est_note")}</p>`}
function pageEstimator(){if(QUOTE_PKG.has(state.est.type))state.est.type="web";const e=state.est,R=(name,val,label,type="radio")=>`<label><input type="${type}" name="${name}" value="${val}" data-est="${name}" ${type==="radio"?(e[name]===val?"checked":""):(e.feat.includes(val)?"checked":"")}><span>${label}</span></label>`;
 return `<div class="wrap phead"><h1>${t("est_h")}</h1><p>${t("est_p")}</p></div><div class="wrap est"><form class="est-q" onsubmit="return false">
  <div><h3>${t("est_type")}</h3><div class="cr">${["web","corp","ecom"].map(k=>R("type",k,t("s_"+k))).join("")}</div><p class="note" style="margin:10px 0 0">${t("quote_only_note")} <a class="link" href="#/proposal">${t("req_btn")} ›</a></p></div>
  <div><h3>${t("est_pages")} <output id="pagesV">${e.pages}</output></h3><input type="range" min="1" max="80" value="${e.pages}" data-est="pages" aria-label="${t("est_pages")}"></div>
  <div><h3>${t("est_langs")} <output id="langsV">${e.langs}</output></h3><input type="range" min="1" max="5" value="${e.langs}" data-est="langs" aria-label="${t("est_langs")}"></div>
  <div><h3>${t("est_feat")}</h3><div class="cr">${Object.entries(FEAT).map(([k,[l]])=>R("feat",k,l,"checkbox")).join("")}</div></div>
  <div><h3>${t("est_design")}</h3><div class="cr">${[["tpl","d_tpl"],["custom","d_custom"],["premium","d_premium"]].map(([k,l])=>R("design",k,t(l))).join("")}</div></div>
  <div><h3>${t("est_growth")}</h3><div class="cr">${[["none",t("g_none")],["seo",t("s_seo")],["seogeo",t("s_seo")+" + GEO"]].map(([k,l])=>R("growth",k,l)).join("")}</div></div>
  <div class="cr"><label><input type="checkbox" data-est="rush" ${e.rush?"checked":""}><span>${t("est_rush")}</span></label></div>${promoOn()?`<label class="est-promo"><input type="checkbox" data-est="promo" ${e.promo?"checked":""} style="width:20px;height:20px;accent-color:#FF5DA2"> <span class="pp-badge">−${PCT}%</span> ${t("est_promo")} · ${t("promo_until").replace("{d}",promoDate())}</label>`:""}
 </form><aside class="est-out" id="estOut" aria-live="polite">${estOut()}</aside></div>`}

function pageLead(kind){const geo=kind==="assessment";
 const gets=geo?tx("leadGeo",["How ChatGPT, Gemini, Perplexity, Copilot and Claude describe your brand today","Entity and business-detail consistency across Google, Bing and key directories","Structured data and crawl access check, including AI crawlers","Five answer-first content opportunities your competitors have not taken","A 30-minute walkthrough call with a search specialist"]):tx("leadAudit",["Speed and Core Web Vitals on mobile and desktop","Mobile layout and usability issues, page by page","Technical SEO: indexing, metadata, redirects, sitemap, schema","Accessibility and security quick checks","A prioritised fix list with effort and impact"]);
 return `<div class="wrap phead"><h1>${t(geo?"geoa_h":"audit_h")}</h1><p>${t(geo?"geoa_p":"audit_p")}</p></div>
 <div class="wrap lead2"><div><h2 class="h2" style="font-size:1.5rem">${t("what_get")}</h2><ul class="ticks">${gets.map(g=>`<li>${g}</li>`).join("")}</ul>
  <div class="callout" style="margin-top:28px">${t("lead_note")}</div>
  ${geo?`<p><a class="link" href="#/" data-goto="score">${t("score_h")}</a></p>`:`<p><a class="link" href="#/estimator">${t("est_h")}</a></p>`}</div>
 <div class="fcard" id="leadBox"><form class="form" data-form="lead" style="max-width:none"><input type="hidden" name="kind" value="${kind}">
  <label>${t("website_url")}<input class="inp" name="url" type="url" required placeholder="https://" dir="ltr"></label>
  <div class="two"><label>${t("name")}<input class="inp" name="n" required autocomplete="name"></label><label>${t("email")}<input class="inp" name="e" type="email" required dir="ltr" autocomplete="email"></label></div>
  ${geo?`<label>${t("brand_name")}<input class="inp" name="brand" required></label><fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:600;font-size:14px;margin-bottom:8px">${t("markets")}</legend><div class="cr">${["UK","US","Europe","GCC","China","Australia","Canada"].map(m=>`<label><input type="checkbox" name="m_${m}"><span>${m}</span></label>`).join("")}</div></fieldset><label>${t("competitors")}<input class="inp" name="comp" placeholder="competitor.com, another.com" dir="ltr"></label>`:`<label>${t("main_goal")}<select class="inp" name="goal"><option>${t("g_leads")}</option><option>${t("g_sales")}</option><option>${t("g_book")}</option><option>${t("g_trust")}</option></select></label>`}
  <button class="btn btn-accent btn-lg" type="submit" style="justify-self:start">${t("send_req")}</button></form></div></div>`}

const CMP_ROWS=[["Best for","Content-led business sites and blogs","Product stores that want to launch fast","Unique products, portals and high-scale sites"],["Typical setup with Penta","£745–£2,000","£1,750–£4,000","£3,000+"],["Monthly running cost","Low; hosting and plugin care","Shopify plan + apps","Hosting and care; no licence fees"],["Speed","Good with care; plugins can slow it","Good, managed by Shopify","Fastest; built to a performance budget"],["SEO control","Strong","Good; some URL limits","Complete"],["Design freedom","High with a custom theme","Theme-based, high with custom work","Unlimited"],["E-commerce","WooCommerce, flexible","Best-in-class checkout","Anything, built to order"],["Multilingual & RTL","Plugins, good","Built-in markets, good","Native, complete"],["Who edits content","Your team, easy","Your team, easy","Your team via headless CMS"],["Scales to","Medium traffic","Large catalogues","Enterprise traffic and logic"]];
state.cmp={sell:"some",custom:"some",budget:"balanced"};
function cmpPick(){const c=state.cmp;const s=[ (c.sell!=="core")+(c.custom!=="lots")+(c.budget!=="invest")+(c.sell==="none"), (c.sell==="core")*2+(c.custom==="none")+(c.budget!=="invest"), (c.custom==="lots")*2+(c.budget==="invest")+(c.sell==="core"&&c.custom!=="none")];return s.indexOf(Math.max(...s))}
function pageCompare(){const w=cmpPick(),names=["WordPress","Shopify",t("cmp_custom")],svcFor=["web","ecom","saas"];const Q=(k,label,opts)=>`<div><h3 style="font:700 1rem var(--body);margin:0 0 8px">${label}</h3><div class="cr">${opts.map(([v,l])=>`<label><input type="radio" name="${k}" value="${v}" data-cmp="${k}" ${state.cmp[k]===v?"checked":""}><span>${l}</span></label>`).join("")}</div></div>`;
 return `<div class="wrap phead"><h1>${t("cmp_h")}</h1><p>${t("cmp_p")}</p></div><div class="wrap" style="padding-bottom:90px;display:grid;gap:28px">
 <div class="fcard" style="display:grid;gap:18px"><h2 class="h2" style="font-size:1.4rem;margin:0">${t("cq_h")}</h2>${Q("sell",t("cq1"),[["none",t("cq1a")],["some",t("cq1b")],["core",t("cq1c")]])}${Q("custom",t("cq2"),[["none",t("cq2a")],["some",t("cq2b")],["lots",t("cq2c")]])}${Q("budget",t("cq3"),[["lean",t("cq3a")],["balanced",t("cq3b")],["invest",t("cq3c")]])}
  <div class="recbox" id="cmpRec">${t("cq_rec")} <b>${names[w]}</b>. <button class="btn btn-accent btn-sm" style="margin-inline-start:8px" data-action="add" data-id="${svcFor[w]}">${t("add_to_cart")}: ${t("s_"+svcFor[w])}</button></div></div>
 <div class="tbl-wrap"><table class="tbl" id="cmpT"><thead><tr><th></th>${names.map((n,i)=>`<th class="${i===w?"win":""}">${n}</th>`).join("")}</tr></thead><tbody>${tx("cmpRows",CMP_ROWS).map(r=>`<tr><td><b>${r[0]}</b></td>${r.slice(1).map((c,i)=>`<td class="${i===w?"win":""}">${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>`}

const ARTS=[["GEO","What Generative Engine Optimisation really is (and isn't)",6,"#0E2A47","GEO is the work of making your business easy for AI assistants to find, understand and cite. It is not a trick or a special tag: Google's own guidance says useful original content and strong SEO fundamentals are what AI search features draw on.|In practice that means a clear one-sentence description of what you do on every key page, consistent business details everywhere online, pages that answer real questions directly, and evidence such as case studies and named experts.|We measure GEO with a fixed panel of buyer questions asked monthly across the major assistants, so progress is visible instead of guessed."],
 ["SEO","The technical SEO checklist for a new website launch",8,"#2A5C96","Most traffic lost in a redesign is lost on launch day. Map every old URL to a new one, keep permanent redirects in place for at least a year, and submit fresh sitemaps to Google and Bing.|Check that staging was never indexed, canonicals point to the live domain, and every language version links to the others with hreflang.|After launch, watch coverage reports daily for two weeks. Problems caught in week one cost hours; caught in month three, they cost rankings."],
 ["Design","Why your homepage has eight seconds, not eight sections",5,"#00AEEF","Visitors decide quickly whether they are in the right place. The first screen should say what you do, who it is for and what to do next, in plain words.|Everything below the fold should answer the next question a buyer has: proof, price, process, people. Sections that answer nobody's question are cost, not content.|Test it: show your homepage for five seconds to someone outside the business and ask what you sell."],
 ["E-commerce","Selling in GCC, Europe and the UK from one store",7,"#1A4170","One store can serve several markets if each market gets its own currency, tax handling, shipping rules and language version.|Arabic storefronts need true right-to-left layouts, not mirrored icons alone, and local payment options increase conversion noticeably.|Keep one product catalogue, localise descriptions properly, and give each market its own URL path so search engines can rank it locally."],
 ["Security","Five website security basics every business should have",4,"#4479B8","Keep the CMS, plugins and server software updated; most compromises use old, known flaws.|Use strong unique passwords with two-factor authentication for every admin account, and remove accounts for people who have left.|Take daily off-site backups and test restoring them. Add a web application firewall, and monitor uptime so you hear about problems before customers do."],
 ["Development","WordPress, Shopify or custom: making the call",6,"#16365C","Choose WordPress when content and flexibility matter most, Shopify when selling products is the business, and custom development when your process or scale is unique.|The cheapest build is rarely the cheapest site to own. Compare three-year cost: setup, monthly fees, apps or plugins, and the time your team spends working around limits.|Use our comparison tool to see a recommendation based on your answers."]];
state.insCat="all";
function pageInsights(){const AR=artsX();const cats=["all",...new Set(AR.map(a=>a[0]))];if(!cats.includes(state.insCat))state.insCat="all";const list=AR.map((a,i)=>[a,i]).filter(([a])=>state.insCat==="all"||a[0]===state.insCat);
 return `<div class="wrap phead"><h1>${t("ins_h")}</h1><p>${t("ins_p")}</p><div class="chips">${cats.map(c=>`<button class="chip" data-action="inscat" data-c="${c}" aria-pressed="${state.insCat===c}">${c==="all"?t("all"):c}</button>`).join("")}</div></div>
 <div class="wrap ins" style="padding-bottom:90px">${list.map(([a,i])=>`<a class="acard" href="#/insights/${a[5]}"><div class="top" style="background:linear-gradient(135deg,${a[3]},#00AEEF)"><span style="--f1:#fff;--f2:rgba(255,255,255,.85);--f3:rgba(255,255,255,.65);--f4:rgba(255,255,255,.5);--f5:rgba(255,255,255,.35)">${logoSVG(56)}</span></div><div class="b"><span class="cat">${a[0]} · ${a[2]} ${t("min")}</span><h3>${a[1]}</h3><p>${a[4].split("|")[0].slice(0,120)}…</p></div></a>`).join("")}</div>`}

function pageCare(){const ids=["care","careb","carea"];
 return `<div class="wrap phead"><h1>${t("care_h")}</h1><p>${t("care_p")}</p></div><div class="wrap" style="padding-bottom:90px"><div class="plans">${ids.map((id,i)=>{const s=SVC[id];return `<article class="pkg ${i===1?"hot":""}">${i===1?`<span class="badge">${t("popular")}</span>`:""}<span class="tier">${t("care_t"+(i+1))}</span><h3>${t("s_"+id)}</h3><p class="for">${t("s_"+id+"_d")}</p><ul>${(tx("careInc",{})[id]||s.inc).map(x=>`<li>${x}</li>`).join("")}</ul><p class="from"><b>${money(s.mo)}${t("per_month")}</b>${t("trust_2")}</p><button class="btn ${i===1?"btn-accent":"btn-primary"}" data-action="add" data-id="${id}">${inCart(id)?"✓ "+t("added"):t("add_to_cart")}</button></article>`}).join("")}</div>
 <div class="callout" style="margin-top:28px">${t("care_note")}</div></div>`}

const PRT_M=[["Referral partner","Introduce clients and earn 10% of their first-year value. We handle sales, delivery and support.",["Co-branded proposal templates","Partner dashboard and payout tracking","Quarterly payouts"]],["White-label delivery","We build, host and optimise under your brand at partner rates. Your client never sees us.",["Your branding on reports and staging","Dedicated project lead","Wholesale pricing on every package"]],["Technology alliance","For software vendors and agencies who want an implementation partner in the UK, EU, GCC and Asia.",["Joint solutions and listings","Shared pipeline","Certified implementation team"]]];
function pagePartners(){const M=tx("prt",PRT_M); return `<div class="wrap phead"><h1>${t("prt_h")}</h1><p>${t("prt_p")}</p></div><div class="wrap" style="padding-bottom:40px"><div class="plans">${M.map((m,i)=>`<article class="pkg ${i===1?"hot":""}"><span class="tier">${t("prt_t"+(i+1))}</span><h3>${m[0]}</h3><p class="for">${m[1]}</p><ul>${m[2].map(x=>`<li>${x}</li>`).join("")}</ul></article>`).join("")}</div></div>
 <div class="wrap lead2"><div><h2 class="h2" style="font-size:1.5rem">${t("prt_apply_h")}</h2><p class="lead">${t("prt_apply_p")}</p></div>
 <div class="fcard" id="leadBox"><form class="form" data-form="lead" style="max-width:none"><input type="hidden" name="kind" value="partner"><div class="two"><label>${t("name")}<input class="inp" name="n" required></label><label>${t("email")}<input class="inp" type="email" name="e" required dir="ltr"></label></div><div class="two"><label>${t("c_company")}<input class="inp" name="c" required></label><label>${t("model")}<select class="inp" name="model">${M.map(m=>`<option>${m[0]}</option>`).join("")}</select></label></div><label>${t("c_msg")}<textarea class="inp" name="m"></textarea></label><button class="btn btn-accent btn-lg" type="submit" style="justify-self:start">${t("send_req")}</button></form></div></div>`}

function showSet(){const v=$("#stageV");if(!v)return;v.querySelectorAll("img").forEach((im,i)=>im.classList.toggle("on",i===showI));document.querySelectorAll(".stage-dots i").forEach((d,i)=>d.classList.toggle("on",i===showI));document.querySelectorAll(".stage-tabs button").forEach(b=>b.setAttribute("aria-selected",+b.dataset.i===showI))}
function selToggle(k,el){const v=el.dataset.v,a=SS[k],i=a.indexOf(v);if(i>=0)a.splice(i,1);else a.push(v);document.querySelectorAll(`[data-action][data-v="${CSS.escape(v)}"]`).forEach(b=>b.setAttribute("aria-pressed",a.includes(v)));const c=$("#selCount");if(c)c.textContent=t("sel_count").replace("{n}",SS.opts.length+SS.extras.length+SS.tech.length);const q=$("#quoteSel");if(q)q.innerHTML=selChips()}
function afterRender(){tplAfterRender();clearInterval(showTimer);const st=$(".stage");if(st&&!matchMedia("(prefers-reduced-motion: reduce)").matches){let hold=false;st.addEventListener("mouseenter",()=>hold=true);st.addEventListener("mouseleave",()=>hold=false);st.addEventListener("click",()=>{hold=true;clearInterval(showTimer)});showTimer=setInterval(()=>{if(!hold){showI=(showI+1)%SHOW_K.length;showSet()}},4500)}clearInterval(abTimer);if($("#abTimes"))abTimer=setInterval(()=>{const e=$("#abTimes");if(e)e.innerHTML=officesHTML()},30000);const els=document.querySelectorAll(".count-up");if(!els.length)return;const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
 const run=el=>{if(reduce)return;const to=+el.dataset.to,t0=performance.now(),d=1400;const step=n=>{const p=Math.min(1,(n-t0)/d);el.textContent=Math.round(to*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(step)};el.textContent="0";requestAnimationFrame(step)};
 if(!("IntersectionObserver" in window))return;const io=new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting){run(en.target);io.unobserve(en.target)}}),{threshold:.6});els.forEach(el=>io.observe(el))}

