 estadd(){const e=state.est;addSvc(e.type,true);for(let i=1;i<e.langs;i++)addSvc("lang",true);if(e.growth!=="none")addSvc("seo",true);if(e.growth==="seogeo")addSvc("geo",true);save();toast(t("added")+": "+t("s_"+e.type));location.hash="#/cart"},
 inscat(el){state.insCat=el.dataset.c;rerenderKeepScroll()},
 art(el){const a=artsX()[+el.dataset.i];const dlg=$("#invDlg");dlg.innerHTML=`<div class="dlg"><button class="dlg-x" data-action="closedlg" aria-label="Close">×</button><p class="cat" style="clear:both">${a[0]} · ${a[2]} ${t("min")}</p><h2 style="font-size:1.6rem">${a[1]}</h2>${a[4].split("|").map(p=>`<p style="color:var(--ink-2)">${p}</p>`).join("")}<div class="stripe" style="border-radius:3px;margin:18px 0"></div><a class="btn btn-accent" href="#/assessment" data-action="closedlg2">${t("geoa_h")}</a></div>`;dlg.showModal()},
