document.addEventListener("click",e=>{const a=e.target.closest("a[href]");if(!a||e.defaultPrevented||e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.hasAttribute("download"))return;
 let href=a.getAttribute("href");if(href.startsWith("#/"))href=hashToPath(href);else if(!(href.startsWith("/")&&(LANG_CODES.includes(href.split("/")[1])||LANG_CODES.includes(href.replace(/^\/penta-services-agency/, "").split("/")[1]))))return;e.preventDefault();go(href)});

