const TPL_BY={};TPL_IDS.forEach(ind=>TPL_MOCKS[ind].forEach((m,k)=>{m.ind=ind;m.k=k;m.pkg=m.pkg||MK_IND[ind].pkg;TPL_BY[m.id]=m}));

/* Mockup renderer: mkPage(m, pageIndex) returns a 1200px-wide page (scaled to fit by tplFit / tplFitView). */
let MKN=0;
function mkLum(h){h=String(h).replace("#","");if(h.length===3)h=h.replace(/./g,"$&$&");const n=parseInt(h,16);return(.2126*(n>>16&255)+.7152*(n>>8&255)+.0722*(n&255))/255}
function mkMix(a,b,w){const f=h=>{h=h.replace("#","");return[0,2,4].map(i=>parseInt(h.substr(i,2),16))},x=f(a),y=f(b);return"#"+x.map((v,i)=>Math.round(v*(1-w)+y[i]*w).toString(16).padStart(2,"0")).join("")}
function mkCols(m){const [bg,ink,P,A,S0]=m.c,dark=mkLum(bg)<.35,S=dark&&mkLum(S0)>.5?mkMix(bg,"#ffffff",.09):S0,D=mkLum(ink)<.5?ink:bg,L=dark?ink:bg,btn=dark||m.v===1&&mkLum(P)<.3&&mkLum(bg)<.35?A:P;return{bg,ink,P,A,S,dark,D,L,btn,btnInk:mkLum(btn)>.6?"#111":"#fff",panInk:mkLum(P)>.6?ink:"#fff"}}
/* Real photography (Unsplash License, self-hosted in /assets/tpl/):
   <design>-hero(-s).webp, <design>-s1/-s2.webp, <design>-i1..i6.webp (own products/posts/properties/services),
   <industry>-p1..p6.webp (shared item photos, aligned with MK_IND items/svcs order), team-1..12.webp (portraits). */
const MK_IMG=getAssetPath("assets/tpl/");
const MK_OWN_ITEMS=new Set(["bloom-co","oak-street","velo","little-sprouts","crown-jewellers","noir-skincare","urban-threads","grind-coffee","volt","pawsome","slow-kitchen","wander-notes","finwise","code-coffee","green-living","prime-estates","skyline-residences","coastal-homes","marina-crest","urban-lettings","fitpulse","dine-now","ride-easy","mint-wallet","staybook","olive-thyme","bright-smile","iron-core","glow-salon","swift-plumbing"]);
let MK_THUMB=false;
function mkSrc(m,key){if(key==="hero")return MK_IMG+m.id+"-hero"+(MK_THUMB?"-s":"")+".webp";
 if(key==="s1"||key==="s2")return MK_IMG+m.id+"-"+key+".webp";
 if(key[0]==="i"){const n=((+key.slice(1)-1)%6)+1;return MK_OWN_ITEMS.has(m.id)?MK_IMG+m.id+"-i"+n+".webp":MK_IMG+m.ind+"-p"+n+".webp"}
 return MK_IMG+"team-"+(((+key.slice(1)-1)%12+12)%12+1)+".webp"}
function mkImg(m,key,h,cls,w){const s=mkSrc(m,key);const fn=s.split("/").pop();return `<div class="mk-ph${cls?" "+cls:""}" style="height:${h}px${w?";width:"+w:""}"><img src="${s}" alt="" loading="lazy" decoding="async" onerror="if(!this._tried){this._tried=true;this.src='https://pentaservices.co.uk/assets/tpl/'+${JSON.stringify(fn)}}else{this.remove()}"></div>`}
const mkE=x=>esc(String(x));
function mkRot(a,k){k=k%a.length;return a.slice(k).concat(a.slice(0,k))}
function mkIni(n){return n.replace(/&/g," ").split(/\s+/).filter(w=>/^[A-Z]/.test(w)).slice(0,2).map(w=>w[0]).join("")||n[0]}
function mkLogo(m){return `<b class="mk-logo"><i>${mkE(mkIni(m.n))}</i><span>${mkE(m.n)}</span></b>`}
const mkStars=`<span class="mk-stars">★★★★★</span>`;
function mkNav(m,I,over){return `<div class="mk-nav${over?" ov":""}">${mkLogo(m)}<span class="mk-links">${I.nav.map((x,i)=>`<span${i===0?' class="on"':""}>${mkE(x)}</span>`).join("")}</span>${["retail","ecommerce"].includes(m.ind)?`<span class="mk-cart">Bag (2)</span>`:""}<span class="mk-btn">${mkE(I.cta)}</span></div>`}
function mkBtns(I,c){return `<div class="mk-row${c?" c":""}"><span class="mk-btn lg">${mkE(I.cta)} <em>→</em></span><span class="mk-btn gh lg">${mkE(I.cta2)}</span></div>`}
function mkAvs(m){return `<div class="mk-avs">${[1,2,3,4].map(i=>`<i style="background-image:url(${mkSrc(m,"t"+(i+m.k*3))})"></i>`).join("")}<span>${mkStars}<small>Rated 4.9 by our clients</small></span></div>`}
function mkHero(m,I){const v=m.v,h=mkE(m.h),p=mkE(m.p),k=`<small class="mk-kick">${mkE(I.kick)}</small>`,st=I.stats[0];
 if(v===0)return `<div class="mk-hero h0"><div class="mk-htx">${k}<h1>${h}</h1><p>${p}</p>${mkBtns(I)}${mkAvs(m)}</div><div class="mk-hph">${mkImg(m,"hero",600,"r-xl")}${mkImg(m,"s1",200,"mk-float","220px")}<div class="mk-glass"><b>${mkE(st[0])}</b><span>${mkE(st[1])}</span></div></div></div>`;
 if(v===1)return `<div class="mk-hero h1">${mkImg(m,"hero",760,"mk-bgimg")}<div class="mk-shade"></div>${mkNav(m,I,1)}<div class="mk-in">${k}<h1>${h}</h1><p>${p}</p>${mkBtns(I,1)}</div><div class="mk-hstats">${I.stats.map(([a,b])=>`<div><b>${mkE(a)}</b><span>${mkE(b)}</span></div>`).join("")}</div></div>`;
 if(v===2)return `<div class="mk-hero h2"><div><small class="mk-kick">${mkE(I.kick)}</small><h1>${h}</h1></div><div class="mk-h2r"><p>${p}</p>${mkBtns(I)}</div></div><div class="mk-pad">${mkImg(m,"hero",560,"r-md")}<div class="mk-cap"><span>${mkE(m.n)}</span><span>${mkE(I.about[0])}</span><span>Scroll ↓</span></div></div>`;
 if(v===3)return `<div class="mk-hero h3"><div class="mk-pan">${k}<h1>${h}</h1><p>${p}</p>${mkBtns(I)}<div class="mk-pstats">${I.stats.map(([a,b])=>`<div><b>${mkE(a)}</b><span>${mkE(b)}</span></div>`).join("")}</div></div><div class="mk-hph">${mkImg(m,"hero",700,"r-0")}<div class="mk-badge2"><b>${mkE(st[0])}</b><span>${mkE(st[1])}</span></div></div></div>`;
 return `<div class="mk-hero h4">${mkImg(m,"hero",720,"r-0 mk-bgimg")}<div class="mk-shade soft"></div><div class="mk-ov">${k}<h1>${h}</h1><p>${p}</p>${mkBtns(I)}</div><div class="mk-mini">${mkImg(m,"s1",150,"r-md","220px")}${mkImg(m,"s2",150,"r-md","220px")}</div></div>`}
function mkTrust(m,I){if(["retail","ecommerce"].includes(m.ind))return `<div class="mk-usp">${I.feats.map(([a,b])=>`<div><i>✦</i><b>${mkE(a)}</b><span>${mkE(b)}</span></div>`).join("")}</div>`;
 return `<div class="mk-logos"><small>Trusted by teams at</small>${["NORTHWIND","Atlasline","KESTREL","Helixa","ORBITA","Lumenor"].map((x,i)=>`<b class="f${i%3}">${x}</b>`).join("")}</div>`}
const mkSh=(a,b,k,c)=>`<div class="mk-sh${c?" c":""}">${k?`<small class="mk-kick">${mkE(k)}</small>`:""}<h2>${mkE(a)}</h2>${b?`<p>${mkE(b)}</p>`:""}</div>`;
function mkFeats(m,I,bare){const g=`<div class="mk-g3 mk-feats">${I.feats.map(([a,b],i)=>`<div class="mk-feat"><span>0${i+1}</span><h3>${mkE(a)}</h3><p>${mkE(b)}</p></div>`).join("")}</div>`;return bare?g:`<div class="mk-sec">${mkSh("Why "+m.n,"",I.kick)}${g}</div>`}
function mkItemCard(m,I,x,oi,kind){const img=mkImg(m,"i"+(oi+1),kind==="land"?260:kind==="tall"?340:300);
 if(m.ind==="realestate")return `<div class="mk-item prop">${img}<span class="mk-tag">${oi%3===0?"New":"Featured"}</span><div class="mk-it"><span class="mk-pr">${mkE(x[2])}</span><b>${mkE(x[0])}</b><small>${mkE(x[1])}</small><div class="mk-meta"><span>▢ 1,240 sq ft</span><span>◎ 0.4 mi to station</span></div></div></div>`;
 if(m.ind==="blog")return `<div class="mk-item post">${img}<div class="mk-it"><span class="mk-pill">${mkE(x[2])}</span><b class="serif">${mkE(x[0])}</b><small>${mkE(x[1])} · by ${mkE(I.team[0][0])}</small></div></div>`;
 return `<div class="mk-item">${img}${oi===0&&["retail","ecommerce"].includes(m.ind)?'<span class="mk-tag">Bestseller</span>':""}<div class="mk-it"><b>${mkE(x[0])}</b><small>${mkE(x[1])}</small>${x[2]?`<span class="mk-pr">${mkE(x[2])}</span>`:""}</div></div>`}
function mkItems(m,I,n,cols,off){const k=((I.rk!=null?I.rk:m.k)+(off||0))%I.items.length,L=mkRot(I.items,k);return `<div class="mk-g${cols||3}">${Array.from({length:n||6},(_,i)=>mkItemCard(m,I,L[i%L.length],(i+k)%I.items.length,cols===4?"tall":"")).join("")}</div>`}
function mkSvcs(m,I,n){const photo=["corporate","technology","other"].includes(m.ind);return `<div class="mk-g3">${I.svcs.slice(0,n||6).map(([a,b],i)=>`<div class="mk-svc">${photo?mkImg(m,"i"+(["corporate","technology"].includes(m.ind)?((i+m.k)%6)+1:i+1),210):""}<div class="mk-svt"><span>${String(i+1).padStart(2,"0")}</span><h3>${mkE(a)}</h3><p>${mkE(b)}</p><em>Learn more →</em></div></div>`).join("")}</div>`}
function mkList(m,I){return `<div class="mk-sec">${mkSh(I.listH,"",m.n,0)}${I.list==="svcs"?mkSvcs(m,I):mkItems(m,I,6)}<div class="mk-row c" style="margin-top:44px"><span class="mk-btn gh">View all →</span></div></div>`}
function mkStats(m,I){return `<div class="mk-stats">${mkImg(m,"s2",380,"r-0 mk-bgimg")}<div class="mk-shade pri"></div><div class="mk-stin">${I.stats.map(([a,b])=>`<div><b>${mkE(a)}</b><span>${mkE(b)}</span></div>`).join("")}</div></div>`}
function mkAbout(m,I,rev){return `<div class="mk-sec mk-split${rev?" rev":""}"><div class="mk-col">${mkImg(m,"s1",540,"r-lg")}${mkImg(m,"s2",230,"mk-over","260px")}<div class="mk-badge3"><b>${mkE(I.stats[0][0])}</b><span>${mkE(I.stats[0][1])}</span></div></div><div><small class="mk-kick">${mkE(I.nav[1])}</small><h2>${mkE(I.about[0])}</h2><p>${mkE(I.about[1])}</p><ul class="mk-ul">${I.feats.map(f=>`<li><b>${mkE(f[0])}</b> ${mkE(f[1])}</li>`).join("")}</ul><span class="mk-btn">${mkE(I.cta2)} →</span></div></div>`}
function mkQuote(m,I){return `<div class="mk-quote">${mkStars}<p>“${mkE(I.quote[0])}”</p><div class="mk-qby"><i style="background-image:url(${mkSrc(m,"t"+(m.k*2+5))})"></i><span><b>${mkE(I.quote[1].split(",")[0])}</b><small>${mkE(I.quote[1].split(",").slice(1).join(",")||m.n)}</small></span></div></div>`}
function mkCta(m,I){return `<div class="mk-cta">${mkImg(m,"hero",420,"r-0 mk-bgimg")}<div class="mk-shade side"></div><div class="mk-ctin"><small class="mk-kick">${mkE(m.n)}</small><h2>${mkE(I.ctaH)}</h2><div class="mk-row"><span class="mk-btn lg inv">${mkE(I.cta)} →</span></div></div></div>`}
function mkFoot(m,I){return `<div class="mk-foot"><div>${mkLogo(m)}<p>${mkE(m.p)}</p><span class="mk-soc"><i>in</i><i>ig</i><i>fb</i><i>x</i></span></div><div><b>Explore</b>${I.nav.map(x=>`<span>${mkE(x)}</span>`).join("")}</div><div><b>Contact</b><span>12 Sample Street</span><span>London EC1A 1AA</span><span>hello@example.com</span><span>020 0000 0000</span></div><div><b>Newsletter</b><span>News, offers and stories. No spam.</span><span class="mk-inp">Your email <em>→</em></span></div><small>© 2027 ${mkE(m.n)}. All rights reserved.<span>Privacy · Terms · Cookies</span></small></div>`}
function mkPHead(m,I,title,sub){return `<div class="mk-phd">${mkImg(m,"s2",380,"r-0 mk-bgimg")}<div class="mk-shade"></div><div class="mk-phin"><small>Home / ${mkE(title)}</small><h1>${mkE(title)}</h1>${sub?`<p>${mkE(sub)}</p>`:""}</div></div>`}
function mkTeam(m,I,off){return `<div class="mk-g4">${(off?[["Hannah Cole","Senior Associate"],["Arjun Mehta","Associate"],["Sofia Rossi","Client Coordinator"],["Lewis Grant","Analyst"]]:I.team).map(([n,r],i)=>`<div class="mk-person">${mkImg(m,"t"+(i+1+(off||0)+m.k*2),330,"r-md")}<b>${mkE(n)}</b><small>${mkE(r)}</small></div>`).join("")}</div>`}
function mkForm(m,I){const F=I.form&&I.form.length?I.form:["Name","Email","Phone","Message"];return `<div class="mk-form mk-card">${F.map((f,i)=>`<label>${mkE(f)}<span class="mk-inp${i===F.length-1?" ta":""}"></span></label>`).join("")}<span class="mk-btn lg">Send message →</span></div>`}
const MK_PG={home:"Home",about:"About",services:"Services",team:"Our team",contact:"Contact us",work:"Work",project:"Project",shop:"Shop",product:"Product",stores:"Our stores",checkout:"Your basket",articles:"Journal",post:"Article",features:"Features",pricing:"Pricing",events:"What's on",event:"Event",gallery:"Gallery",tickets:"Tickets",projects:"Our projects",donate:"Donate",courses:"Courses",course:"Course",admissions:"Admissions",listings:"Properties",property:"Property",agents:"Our agents",story:"Our story",details:"The details",rsvp:"RSVP",menu:"Services & prices",booking:"Book online",s_home:"Home",s_detail:"Detail",s_cart:"Checkout",s_profile:"Profile"};
function mkSub(m,I,type,lab){const T=MK_PG[lab]||lab,nav=mkNav(m,I),foot=mkFoot(m,I);
 switch(type){
 case"about":return nav+mkPHead(m,I,T,I.about[0])+mkAbout(m,I,1)+mkStats(m,I)+`<div class="mk-sec">${mkSh(MK_PG.team,"",m.n)}${mkTeam(m,I)}</div>`+mkQuote(m,I)+mkCta(m,I)+foot;
 case"services":return nav+mkPHead(m,I,T,m.p)+`<div class="mk-sec">${mkSvcs(m,I)}</div><div class="mk-sec alt">${mkSh("How we work","",m.n)}${mkFeats(m,I,1)}</div>`+mkQuote(m,I)+mkCta(m,I)+foot;
 case"team":return nav+mkPHead(m,I,T,I.about[1])+`<div class="mk-sec">${mkTeam(m,I)}</div><div class="mk-sec alt">${mkTeam(m,I,4)}</div>`+mkCta(m,I)+foot;
 case"contact":return nav+mkPHead(m,I,T,I.ctaH)+`<div class="mk-sec mk-contact">${mkForm(m,I)}<div><div class="mk-card"><h3>${mkE(m.n)}</h3><p>12 Sample Street<br>London EC1A 1AA</p><p>020 0000 0000<br>hello@example.com</p><p><b>Opening hours</b><br>Mon–Fri 9:00–18:00<br>Sat 10:00–16:00</p></div>${mkImg(m,"s1",240,"r-lg")}</div></div><div class="mk-map"><i></i><span>${mkE(m.n)}</span></div>`+foot;
 case"listing":return nav+mkPHead(m,I,T,m.p)+`<div class="mk-sec"><div class="mk-filter"><span class="on">All</span>${(m.ind==="blog"?[...new Set(I.items.map(x=>x[2]))].slice(0,4):MK_FILTERS[m.ind]||["Featured","Popular","New","Offers"]).map(x=>`<span>${mkE(x)}</span>`).join("")}<span class="mk-sort">Sort: Featured ▾</span></div>${mkItems(m,I,9,3,1)}<div class="mk-pages"><span class="on">1</span><span>2</span><span>3</span><span>→</span></div></div>`+mkCta(m,I)+foot;
 case"detail":{const k=(I.rk!=null?I.rk:m.k)%I.items.length,x=I.items[k],n=k+1;return nav+`<div class="mk-sec"><small class="mk-crumb">Home / ${mkE(MK_PG[I.pages[1][1]]||"")} / ${mkE(x[0])}</small><div class="mk-detail"><div>${mkImg(m,"i"+n,560,"r-lg")}<div class="mk-thumbs">${mkImg(m,"i"+n,110,"r-md on")}${mkImg(m,"s1",110,"r-md")}${mkImg(m,"s2",110,"r-md")}${mkImg(m,"hero",110,"r-md")}</div></div><div><small class="mk-kick">${mkE(x[1])}</small><h1>${mkE(x[0])}</h1>${mkStars} <small class="mk-rev">128 reviews</small>${x[2]?`<p class="mk-big">${mkE(x[2])}</p>`:""}<p>${mkE(I.about[1])}</p><div class="mk-row"><span class="mk-btn lg">${mkE(I.cta)} →</span><span class="mk-btn gh lg">♡ Save</span></div><div class="mk-acc">${I.feats.map(f=>`<p><b>${mkE(f[0])}</b><span>${mkE(f[1])}</span></p>`).join("")}</div></div></div></div><div class="mk-sec alt">${mkSh("You may also like","",m.n)}${mkItems(m,I,3,3,2)}</div>`+foot}
 case"post":{const k=m.k%I.items.length,x=I.items[k];return nav+`<div class="mk-post"><small class="mk-kick">${mkE(x[2])} · ${mkE(x[1])}</small><h1>${mkE(x[0])}</h1><div class="mk-by"><i style="background-image:url(${mkSrc(m,"t"+(m.k*2+1))})"></i><span><b>${mkE(I.team[0][0])}</b><small>12 March 2027</small></span></div></div>${mkImg(m,"i"+(k+1),560,"r-0")}<div class="mk-post"><p class="mk-lead">${mkE(I.about[1])}</p><p>${mkE(I.feats[0][1])} ${mkE(I.about[1])}</p><h2>${mkE(I.feats[1][0])}</h2><p>${mkE(I.feats[1][1])} ${mkE(I.feats[2][1])}</p>${mkImg(m,"s1",420,"r-lg")}<blockquote>${mkE(I.quote[0])}</blockquote><h2>${mkE(I.feats[2][0])}</h2><p>${mkE(I.feats[2][1])} ${mkE(I.feats[0][1])}</p></div><div class="mk-sec alt">${mkSh("Keep reading","",m.n)}${mkItems(m,I,3,3,2)}</div>`+mkCta(m,I)+foot}
 case"checkout":{const k=m.k%I.items.length;const L=[0,1,2].map(j=>[(k+j)%I.items.length,I.items[(k+j)%I.items.length]]);return nav+`<div class="mk-sec mk-co"><div><h1 class="mk-coh">${mkE(T)}</h1>${L.map(([oi,x])=>`<div class="mk-line">${mkImg(m,"i"+(oi+1),120,"r-md","120px")}<div><b>${mkE(x[0])}</b><small>${mkE(x[1])}</small><span class="mk-qty">− 1 +</span></div><b>${mkE(x[2])}</b></div>`).join("")}<div class="mk-card"><h3>Delivery details</h3><div class="mk-form two">${["Full name","Email","Address","Postcode"].map(f=>`<label>${f}<span class="mk-inp"></span></label>`).join("")}</div></div></div><div class="mk-card mk-sum"><h3>Order summary</h3><p><span>Subtotal</span><b>£162.00</b></p><p><span>Delivery</span><b>Free</b></p><p><span>Discount code</span><b class="mk-inp sm">WELCOME10</b></p><p class="tot"><span>Total</span><b>£162.00</b></p><span class="mk-btn lg">Secure checkout →</span><div class="mk-pay"><i>VISA</i><i>Mastercard</i><i> Pay</i><i>G Pay</i><i>PayPal</i></div><small>Free returns within 30 days</small></div></div>`+foot}
 case"gallery":{const keys=["hero","i1","i2","s1","i3","i4","s2","i5","i6"];return nav+mkPHead(m,I,T,m.p)+`<div class="mk-sec"><div class="mk-filter"><span class="on">All</span>${(MK_FILTERS[m.ind]||["Ceremony","Reception","Portraits","Details"]).slice(0,4).map(x=>`<span>${mkE(x)}</span>`).join("")}</div><div class="mk-mas">${keys.map((k2,i)=>mkImg(m,k2,[360,260,300,420,280,320,260,380,300][i],"r-md")).join("")}</div></div>`+mkCta(m,I)+foot}
 case"donate":return nav+`<div class="mk-hero mk-dh">${mkImg(m,"hero",640,"r-0 mk-bgimg")}<div class="mk-shade side"></div><div class="mk-dtx"><small class="mk-kick">${mkE(I.kick)}</small><h1>${mkE(I.ctaH)}</h1><p>${mkE(m.p)}</p></div><div class="mk-card mk-don"><h2>Make a donation</h2><div class="mk-seg"><span class="on">Monthly</span><span>One-off</span></div><div class="mk-amt">${["£10","£25","£50","£100"].map((a,i)=>`<span${i===1?' class="on"':""}>${a}</span>`).join("")}</div><p>£25 a month funds a project like this for a whole community.</p><label class="mk-chk"><i>✓</i>Add Gift Aid (+25% at no cost to you)</label><span class="mk-btn lg">Donate £25 monthly →</span><small>Secure payment · Cancel any time</small></div></div>`+mkStats(m,I)+`<div class="mk-sec">${mkSh(MK_PG.projects,"",m.n)}<div class="mk-g3">${mkRot(I.items,I.rk!=null?I.rk:m.k).slice(0,3).map((x,i)=>`<div class="mk-item">${mkImg(m,"i"+(((i+(I.rk!=null?I.rk:m.k))%6)+1),260)}<div class="mk-it"><b>${mkE(x[0])}</b><small>${mkE(x[1])}</small><div class="mk-bar"><i style="width:${[72,58,86][i]}%"></i></div><span class="mk-pr">${mkE(x[2])}</span></div></div>`).join("")}</div></div>`+mkQuote(m,I)+foot;
 case"pricing":return nav+mkPHead(m,I,T,"Simple pricing. Cancel any time.")+`<div class="mk-sec"><div class="mk-g3">${I.tiers.map(([n,p,d,f],i)=>`<div class="mk-card mk-tier${i===1?" on":""}">${i===1?'<small class="mk-badge">Most popular</small>':""}<h3>${mkE(n)}</h3><p>${mkE(d)}</p><p class="mk-big">${mkE(p)}${p.startsWith("£")&&!p.includes("/")&&p!=="£0"?`<small>${I.tierSuffix||"/user/mo"}</small>`:""}</p><ul class="mk-ul">${f.map(x=>`<li>${mkE(x)}</li>`).join("")}</ul><span class="mk-btn${i===1?"":" gh"}">${i===2?"Contact sales":"Start free trial"}</span></div>`).join("")}</div></div>${mkTrust(m,I)}<div class="mk-sec alt">${mkSh("Frequently asked questions","",m.n)}<div class="mk-faq">${["Can I change plans later?","Is there a free trial?","How secure is my data?","Do you offer discounts?"].map(q=>`<p>${q}<span>+</span></p>`).join("")}</div></div>`+mkCta(m,I)+foot;
 }return ""}
/* mobile app boards */
function mkScreen(m,I,kind){const L=mkRot(I.items,m.k),k=m.k%I.items.length,ii=j=>"i"+(((k+j)%6)+1),bar=`<div class="ap-st"><b>9:41</b><span>●●● ◔</span></div>`,tabs=`<div class="ap-tab">${(I.tabs||I.nav).map((x,i)=>`<span${i===({s_home:0,s_detail:1,s_cart:2,s_profile:3}[kind]||0)?' class="on"':""}><i></i>${mkE(x)}</span>`).join("")}</div>`;
 let body="";
 if(kind==="s_home")body=`<div class="ap-h"><span><small>Good morning, Alex</small><b>${mkE(m.n)}</b></span><i style="background-image:url(${mkSrc(m,"t"+(m.k+2))})"></i></div><div class="ap-search">⌕ Search</div><div class="ap-hero">${mkImg(m,ii(0),150,"r-0")}<div><b>${mkE(L[0][0])}</b><span class="mk-btn">${mkE(L[0][2])}</span></div></div><div class="ap-chips">${["All","Popular","New","Near you"].map((x,i)=>`<span${i?"":' class="on"'}>${x}</span>`).join("")}</div>${L.slice(1,4).map((x,i)=>`<div class="ap-row">${mkImg(m,ii(i+1),58,"r-sm","58px")}<div><b>${mkE(x[0])}</b><small>${mkE(x[1])}</small></div><em>${mkE(x[2])}</em></div>`).join("")}`;
 else if(kind==="s_detail")body=`${mkImg(m,ii(0),270,"r-0")}<div class="ap-pad"><small class="mk-kick">${mkE(L[0][1])}</small><b class="ap-t">${mkE(L[0][0])}</b>${mkStars}<p>${mkE(I.feats[0][1])}</p><div class="ap-stats">${I.stats.map(([a,b])=>`<span><b>${mkE(a)}</b>${mkE(b)}</span>`).join("")}</div><span class="mk-btn ap-full">${mkE(L[0][2])}</span></div>`;
 else if(kind==="s_cart")body=`<div class="ap-h"><span><b>Checkout</b></span></div>${L.slice(0,3).map((x,i)=>`<div class="ap-row">${mkImg(m,ii(i),58,"r-sm","58px")}<div><b>${mkE(x[0])}</b><small>Qty 1</small></div><em>${mkE(x[2])}</em></div>`).join("")}<div class="ap-pad"><p class="ap-sum"><span>Total</span><b>£64.50</b></p><div class="ap-pay"><span class="on"> Pay</span><span>G Pay</span><span>Card</span></div><span class="mk-btn ap-full">Confirm</span></div>`;
 else body=`<div class="ap-prof"><i style="background-image:url(${mkSrc(m,"t"+(m.k+2))})"></i><b>Alex Morgan</b><small>Gold member</small></div><div class="ap-stats">${I.stats.map(([a,b])=>`<span><b>${mkE(a)}</b>${mkE(b)}</span>`).join("")}</div>${["Account","Payment methods","Notifications","Privacy","Help & support"].map(x=>`<div class="ap-set">${x}<span>›</span></div>`).join("")}`;
 return `<div class="ap-ph"><div class="ap-scr">${bar}<div class="ap-body">${body}</div>${tabs}</div></div>`}
function mkBoard(m,I,kind){const T=MK_PG[kind];
 if(kind==="s_home")return `<div class="mk-board">${mkImg(m,"hero",980,"r-0 mk-bgimg")}<div class="mk-shade board"></div><div class="mk-bin">${mkLogo(m)}<h1>${mkE(m.h)}</h1><p>${mkE(m.p)}</p><div class="mk-stores"><span> App Store</span><span>▶ Google Play</span></div><div class="mk-phones">${mkScreen(m,I,"s_detail")}${mkScreen(m,I,"s_home")}${mkScreen(m,I,"s_profile")}</div></div></div><div class="mk-sec">${mkSh("Why people love "+m.n,"",I.kick,1)}${mkFeats(m,I,1)}</div><div class="mk-sec mk-split">${mkImg(m,"s1",460,"r-lg")}<div><small class="mk-kick">${mkE(m.n)}</small><h2>${mkE(I.about[0])}</h2><p>${mkE(I.about[1])}</p><ul class="mk-ul">${I.feats.map(f=>`<li><b>${mkE(f[0])}</b></li>`).join("")}</ul></div></div>${mkStats(m,I)}${mkQuote(m,I)}${mkCta(m,I)}`;
 return `<div class="mk-board one">${mkImg(m,"s"+(kind==="s_cart"?2:1),940,"r-0 mk-bgimg")}<div class="mk-shade board"></div><div class="mk-bin two"><div class="mk-phones">${mkScreen(m,I,kind)}</div><div class="mk-bt"><small class="mk-kick">${mkE(m.n)} · ${mkE(T)}</small><h1>${mkE(T)}</h1><ul class="mk-ul">${I.feats.map(f=>`<li><b>${mkE(f[0])}</b> ${mkE(f[1])}</li>`).join("")}</ul><div class="mk-stores"><span> App Store</span><span>▶ Google Play</span></div></div></div></div>`}
function mkHome(m,I){const v=m.v,nav=v===1||v===4?"":mkNav(m,I),H=v===4?mkNav(m,I,1).replace('mk-nav ov','mk-nav ov abs')+mkHero(m,I):mkHero(m,I),T=mkTrust(m,I),F=mkFeats(m,I),Li=mkList(m,I),S=mkStats(m,I),Q=mkQuote(m,I),C=mkCta(m,I),ft=mkFoot(m,I);
 return [[nav,H,T,Li,mkAbout(m,I),S,F,Q,C,ft],[H,T,Li,mkAbout(m,I,1),F,Q,C,ft],[nav,H,T,Li,F,mkAbout(m,I),Q,C,ft],[nav,H,T,F,mkAbout(m,I,1),Li,S,Q,C,ft],[H,T,Li,S,mkAbout(m,I),F,Q,C,ft]][v].join("")}
function mkPage(m,pi,thumb){if(m.live){const pg=m.pages[pi||0],k=thumb?"thumb":pg[1]==="bmenu"?"menu":pg[1];return `<div class="mkx live" dir="ltr" style="--bg:#fff"><img src="${getAssetPath(`assets/tpl/${m.id}-${k}.jpg`)}" onerror="this.onerror=null;this.src='https://pentaservices.co.uk/assets/tpl/' + m.id + '-' + k + '.jpg';" alt="${esc(m.n)}" loading="lazy" decoding="async" width="1200" height="${thumb?1650:m.shots[pg[1]]}" style="display:block;width:1200px;height:${thumb?1650:m.shots[pg[1]]}px"></div>`}const I=Object.assign({},MK_IND[m.ind],MK_OVR[m.id]||{}),C=mkCols(m),pg=I.pages[pi||0],[f1,f2]=m.f;MK_THUMB=!!thumb;
 const inner=pg[0]==="home"?mkHome(m,I):pg[0]==="app"?mkBoard(m,I,pg[1]):pg[0].startsWith("app")?mkApp(m,I,pg[0],pg[1]):mkSub(m,I,pg[0],pg[1]);MK_THUMB=false;
 const ft=C.dark?mkMix(C.bg,"#ffffff",.05):mkLum(C.ink)<.3?C.ink:mkMix(C.P,"#000000",.55);
 return `<div class="mkx v${m.v}${C.dark?" dark":""}" dir="ltr" lang="en" style="--bg:${C.bg};--ink:${C.ink};--pri:${C.P};--acc:${C.A};--soft:${C.S};--btn:${C.btn};--btn-ink:${C.btnInk};--pan-ink:${C.panInk};--ft:${ft};--hf:${MK_F[f1][1]};--bf:${MK_F[f2][1]}">${inner}</div>`}

