const APP_IC=[IC('<path d="M13 2 4 14h7l-1 8 9-12h-7l1-8Z"/>'),IC('<path d="M3 3v18h18"/><path d="m7 15 4-4 3 3 5-6"/>'),IC('<path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6l-8-3Z"/>'),IC('<path d="M6 8a6 6 0 0 1 12 0c0 7 3 8 3 8H3s3-1 3-8"/><path d="M10 20a2 2 0 0 0 4 0"/>'),IC('<circle cx="9" cy="8" r="3"/><path d="M3 20c0-3 3-5 6-5s6 2 6 5"/><circle cx="17" cy="9" r="2.5"/><path d="M16 15c3 0 5 2 5 5"/>'),IC('<rect x="3" y="6" width="18" height="13" rx="2"/><path d="M3 10h18M7 15h4"/>')];
function mkPhone(m,I,kind,cls){return `<div class="ap-wrap ${cls||""}">${mkScreen(m,I,kind)}</div>`}
const mkBadges=()=>`<div class="ap-badges"><span><i></i><b><small>Download on the</small>App Store</b></span><span><i class="gp">▶</i><b><small>Get it on</small>Google Play</b></span></div>`;
function mkRate(I){return `<div class="ap-rate">${mkStars}<b>${mkE(I.stats[0][0].replace("★",""))}</b><span>${mkE(I.stats[0][1])}</span></div>`}
