function mkAppFeatGrid(m,I){return `<div class="mk-sec">${mkSh("Everything in one app","",m.n,1)}<div class="mk-g3 ap-fg">${(I.f6||I.feats).map(([a,b],i)=>`<div class="ap-fc"><i>${APP_IC[i%6]}</i><h3>${mkE(a)}</h3><p>${mkE(b)}</p></div>`).join("")}</div></div>`}
function mkAppSteps(m,I){const S=[["Download the app","Free on the App Store and Google Play."],["Create your account","Sign up in under a minute with Apple or Google."],["You're all set",(I.f6||I.feats)[0][1]]];return `<div class="mk-sec alt"><div class="ap-steps"><div>${S.slice(0,2).map((s,i)=>`<div class="ap-st2"><span>0${i+1}</span><h3>${mkE(s[0])}</h3><p>${mkE(s[1])}</p></div>`).join("")}</div>${mkPhone(m,I,"s_home","mid")}<div><div class="ap-st2"><span>03</span><h3>${mkE(S[2][0])}</h3><p>${mkE(S[2][1])}</p></div><div class="ap-st2 q">${mkStars}<p>“${mkE((I.reviews||[[I.quote[0]]])[0][0])}”</p></div></div></div></div>`}
function mkAppRows(m,I,n,from){const F=(I.f6||I.feats);return `<div class="mk-sec">${Array.from({length:n},(_,j)=>{const i=(j+(from||0))%F.length,[a,b]=F[i];return `<div class="ap-row2${j%2?" rev":""}"><div class="ap-rart">${mkImg(m,j%2?"s2":"s1",440,"r-xl ap-rbg")}${mkPhone(m,I,APP_KINDS[(i+1)%4],"rowph")}</div><div><small class="mk-kick">0${i+1} · ${mkE(m.n)}</small><h2>${mkE(a)}</h2><p>${mkE(b)} ${mkE(I.about[1])}</p><ul class="mk-ul">${F.filter((_,k)=>k!==i).slice(0,3).map(f=>`<li><b>${mkE(f[0])}</b></li>`).join("")}</ul></div></div>`}).join("")}</div>`}
function mkAppReviews(m,I){const R=I.reviews||[I.quote];return `<div class="mk-sec alt">${mkSh("What our users say","",I.stats[0][0]+" "+I.stats[0][1],1)}<div class="mk-g3">${R.map(([q,w],i)=>`<div class="mk-card ap-rev">${mkStars}<p>“${mkE(q)}”</p><div class="mk-qby"><i style="background-image:url(${mkSrc(m,"t"+(i*2+1+m.k*2))})"></i><span><b>${mkE(w.split(",")[0])}</b><small>${mkE(w.split(",")[1]||"")}</small></span></div></div>`).join("")}</div></div>`}
function mkAppPricing(m,I){return `<div class="mk-sec">${mkSh("Simple, honest pricing","Start free. Upgrade when you're ready.",m.n,1)}<div class="mk-g3">${(I.tiers||[]).map(([n,p,d,f],i)=>`<div class="mk-card mk-tier${i===1?" on":""}">${i===1?'<small class="mk-badge">Most popular</small>':""}<h3>${mkE(n)}</h3><p>${mkE(d)}</p><p class="mk-big">${mkE(p)}${p.startsWith("£")&&!p.includes("/")&&p!=="£0"?`<small>${I.tierSuffix||"/mo"}</small>`:""}</p><ul class="mk-ul">${f.map(x=>`<li>${mkE(x)}</li>`).join("")}</ul><span class="mk-btn${i===1?"":" gh"}">${i===2&&p==="Custom"?"Contact sales":"Get started"}</span></div>`).join("")}</div></div>`}
function mkAppFaq(m,I){return `<div class="mk-sec alt">${mkSh("Questions? Answers.","",m.n,1)}<div class="mk-faq ap-faq">${(I.faq||[]).map(([q,a],i)=>`<div class="${i===0?"open":""}"><p>${mkE(q)}<span>${i===0?"−":"+"}</span></p>${i===0?`<small>${mkE(a)}</small>`:""}</div>`).join("")}</div></div>`}
function mkAppCta(m,I){return `<div class="ap-cta"><div><small class="mk-kick">${mkE(m.n)}</small><h2>${mkE(I.ctaH||"Get the app")}</h2><p>${mkE(m.p)}</p>${mkBadges()}</div>${mkPhone(m,I,"s_detail","peek")}</div>`}
function mkAppLogos(){return `<div class="mk-logos"><small>As featured in</small>${["NORTHWIND","Atlasline","KESTREL","Helixa","ORBITA","Lumenor"].map((x,i)=>`<b class="f${i%3}">${x}</b>`).join("")}</div>`}
function mkAppHero(m,I){const v=m.v,k=`<small class="mk-kick ap-pill">${mkE(I.kick)}</small>`,h=`<h1>${mkE(m.h)}</h1>`,p=`<p>${mkE(m.p)}</p>`;
 if(v===0)return `<div class="mk-hero ah0"><div class="mk-htx">${k}${h}${p}${mkBadges()}${mkRate(I)}</div><div class="ah-art"><div class="ah-blob"></div>${mkPhone(m,I,"s_detail","back")}${mkPhone(m,I,"s_home","front")}<div class="mk-glass ah-chip"><b>${mkE(I.stats[1][0])}</b><span>${mkE(I.stats[1][1])}</span></div></div></div>`;
 if(v===1)return `<div class="mk-hero ah1">${mkImg(m,"hero",980,"r-0 mk-bgimg")}<div class="mk-shade"></div>${mkNav(m,I,1)}<div class="mk-in">${k}${h}${p}${mkBadges()}</div><div class="ah1-ph"><div class="ah-float l"><b>${mkE(I.stats[0][0])}</b><span>${mkE(I.stats[0][1])}</span></div>${mkPhone(m,I,"s_home","big")}<div class="ah-float r"><b>${mkE(I.stats[1][0])}</b><span>${mkE(I.stats[1][1])}</span></div></div></div>`;
 if(v===2)return `<div class="mk-hero ah2"><div>${k}${h}${p}${mkBadges()}${mkRate(I)}</div><div class="ah2-ph">${mkPhone(m,I,"s_home","tilt")}</div></div>`;
 if(v===3)return `<div class="mk-hero ah3"><div class="mk-pan">${k}${h}${p}${mkBadges()}<div class="mk-pstats">${I.stats.map(([a,b])=>`<div><b>${mkE(a)}</b><span>${mkE(b)}</span></div>`).join("")}</div></div><div class="mk-hph">${mkImg(m,"hero",760,"r-0")}${mkPhone(m,I,"s_detail","over")}</div></div>`;
 return `<div class="mk-hero ah4"><div class="ah4-tx">${k}${h}${p}${mkBadges()}</div><div class="ah4-fan">${["s_profile","s_detail","s_home","s_cart","s_profile"].map((kd,i)=>mkPhone(m,I,kd,"f"+i)).join("")}</div></div>`}
function mkAppBento(m,I){const F=I.f6||I.feats;return `<div class="mk-sec">${mkSh("Built for everyday life","",m.n)}<div class="ap-bento"><div class="b1"><h3>${mkE(F[0][0])}</h3><p>${mkE(F[0][1])}</p>${mkPhone(m,I,"s_home","bento")}</div><div class="b2">${mkImg(m,"s1",300,"r-0 mk-bgimg")}<div class="mk-shade"></div><h3>${mkE(F[1][0])}</h3></div><div class="b3"><b>${mkE(I.stats[1][0])}</b><span>${mkE(I.stats[1][1])}</span></div><div class="b4"><i>${APP_IC[2]}</i><h3>${mkE(F[2][0])}</h3><p>${mkE(F[2][1])}</p></div><div class="b5">${mkImg(m,"s2",300,"r-0 mk-bgimg")}<div class="mk-shade"></div><h3>${mkE(F[3][0])}</h3></div><div class="b6"><i>${APP_IC[4]}</i><h3>${mkE(F[4][0])}</h3><p>${mkE(F[4][1])}</p></div></div></div>`}
function mkAppFeatList(m,I){const F=I.f6||I.feats;return `<div class="mk-sec ap-fl"><div class="ap-flph">${mkPhone(m,I,"s_detail","")}</div><div>${mkSh("Why "+m.n,"",I.kick)}<div class="ap-fll">${F.map(([a,b],i)=>`<div><span>0${i+1}</span><h3>${mkE(a)}</h3><p>${mkE(b)}</p></div>`).join("")}</div></div></div>`}
function mkAppVideo(m,I){return `<div class="mk-sec"><div class="ap-video">${mkImg(m,"s1",520,"r-xl")}<div class="mk-shade soft"></div><span class="ap-play">▶</span><div class="ap-vtx"><small class="mk-kick">Watch · 1:24</small><h2>See ${mkE(m.n)} in action</h2></div></div></div>`}
function mkAppMarquee(m,I){return `<div class="ap-marq">${[...(I.f6||I.feats),...(I.f6||I.feats)].slice(0,8).map(f=>`<span>✦ ${mkE(f[0])}</span>`).join("")}</div>`}
function mkAppHome(m,I){const nav=m.v===1?"":mkNav(m,I),H=mkAppHero(m,I),C=mkAppCta(m,I),ft=mkFoot(m,I);
 return [[nav,H,mkAppLogos(),mkAppFeatGrid(m,I),mkAppSteps(m,I),mkAppReviews(m,I),mkAppPricing(m,I),C,ft],
  [H,mkAppMarquee(m,I),mkAppRows(m,I,3),mkStats(m,I),mkAppReviews(m,I),C,ft],
  [nav,H,mkAppFeatList(m,I),mkQuote(m,Object.assign({},I,{quote:(I.reviews||[I.quote])[0]})),mkAppPricing(m,I),mkAppFaq(m,I),C,ft],
  [nav,H,mkAppBento(m,I),mkAppReviews(m,I),mkAppFaq(m,I),C,ft],
  [nav,H,mkAppLogos(),mkAppRows(m,I,2),mkAppVideo(m,I),mkAppPricing(m,I),mkAppFaq(m,I),C,ft]][m.v].join("")}
function mkApp(m,I,type,lab){const T=MK_PG[lab]||lab,nav=mkNav(m,I),C=mkAppCta(m,I),ft=mkFoot(m,I);
 if(type==="apphome")return mkAppHome(m,I);
 if(type==="appfeat")return nav+mkPHead(m,I,T,m.p)+mkAppRows(m,I,6)+mkAppFeatGrid(m,I)+C+ft;
 if(type==="appscreens")return nav+mkPHead(m,I,T,(I.f6||I.feats)[0][1])+`<div class="ap-gal"><div class="ap-galrow">${APP_KINDS.concat(["s_home"]).map((k,i)=>`<figure>${mkPhone(m,I,k,"")}<figcaption>${mkE((I.tabs||I.nav)[i%4])}</figcaption></figure>`).join("")}</div></div>`+mkAppReviews(m,I)+C+ft;
 if(type==="apphelp")return nav+`<div class="ap-help">${mkImg(m,"s2",360,"r-0 mk-bgimg")}<div class="mk-shade pri"></div><div class="ap-hin"><small class="mk-kick">${mkE(T)}</small><h1>How can we help?</h1><span class="mk-inp ap-search">⌕ Search articles</span></div></div><div class="mk-sec"><div class="mk-g4">${[["Getting started",0],["Account & billing",5],["Privacy & security",2],["Troubleshooting",3]].map(([a,i])=>`<div class="mk-card ap-hc"><i>${APP_IC[i]}</i><h3>${a}</h3><p>${3+i} articles</p></div>`).join("")}</div></div>`+mkAppFaq(m,I)+`<div class="mk-sec"><div class="mk-card ap-sup"><div><h3>Still need help?</h3><p>Our support team replies within a few hours, every day.</p></div><span class="mk-btn">Contact support</span></div></div>`+ft;
 return ""}

