function tplTx(id){return((TPL_TX[state.lang]||TPL_TX.en)[id])||TPL_TX.en[id]}
function tplPgl(k){return((TPL_PGL[state.lang]||TPL_PGL.en)[k])||TPL_PGL.en[k]||k}
function tplDesc(m){return m.d[state.lang]||m.d.en}
function mkFonts(){if(document.getElementById("mkFonts"))return;const l=document.createElement("link");l.id="mkFonts";l.rel="stylesheet";l.href=MK_FONTS;document.head.appendChild(l);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>{tplFit(document);tplFitView()})}
function tplSw(m){return `<span class="tpl-sw" aria-hidden="true">${m.c.slice(1).map(c=>`<i style="background:${c}"></i>`).join("")}</span>`}
function tplFrom(id){const s=SVC[id];if(!s)return"";const on=promoOn()&&s.setup>0;return `${t("from")} <b>${money(on?s.setup*(1-PROMO.rate):s.setup)}</b>${on?" "+strike(s.setup):""} + ${money(s.mo)}${t("per_month")}`}
function tplThumb(m,act){return `<button class="tpl-thumb" data-action="${act||"tplopen"}" data-id="${m.id}" aria-label="${esc(t("tpl_view")+": "+m.n)}"><span class="tpl-dots"><i></i><i></i><i></i></span><span class="tpl-sc" aria-hidden="true" data-nosnippet>${mkPage(m,0,1)}</span></button>`}
function tplCard(m){return `<article class="tpl-card${m.live?" is-live":""}" id="design-${m.id}">${m.live?`<span class="tpl-livebadge">● ${t("tpl_livebadge")}</span>`:""}${tplThumb(m)}<div class="tpl-meta"><div><h3>${esc(m.n)}</h3><p>${esc(tplDesc(m).replace(/^./,c=>c.toUpperCase()))} · ${t("st_"+m.v)}</p></div>${tplSw(m)}</div><p class="tpl-pk"><span>${t("s_"+m.pkg)}</span> ${QUOTE_PKG.has(m.pkg)?t("by_proposal"):tplFrom(m.pkg)}</p><div class="tpl-act"><button class="btn btn-ghost btn-sm" data-action="tplopen" data-id="${m.id}">${t("tpl_view")}</button><button class="btn btn-accent btn-sm" data-action="tplbuy" data-id="${m.id}">${QUOTE_PKG.has(m.pkg)?t("tpl_req"):t("tpl_buy")}</button>${m.live?`<a class="link tpl-livelink" href="${m.live}" target="_blank" rel="noopener">${t("tpl_live")}</a>`:""}</div></article>`}
function tplSteps(){return `<section class="sec tint"><div class="wrap"><div class="sec-h"><h2>${t("tpl_steps_h")}</h2></div><ol class="steps tpl-steps">${[1,2,3].map(i=>`<li><h3>${t("tpl_s"+i+"h")}</h3><p>${t("tpl_s"+i)}</p></li>`).join("")}</ol></div></section>`}
function tplMenu(route){const on=route==="templates"||route==="tpl";return `<div class="dd mega ${on?"on":""}" id="ddT"><button data-action="ddT" aria-expanded="false" aria-controls="ddTm">${t("nav_tpl")}</button><div class="dd-menu mm" id="ddTm"><div class="mm-in"><a class="mm-promo" href="#/templates"><span class="mm-wm">${logoSVG(260)}</span><h3>${t("tpl_mm_h")}</h3><p>${t("tpl_mm_p")}</p><div class="mm-mock"><div class="mmk-bar"><i></i><i></i><i></i></div><div class="mmk-hero"><b></b><b></b><span></span></div><div class="mmk-cards"><i></i><i></i><i></i></div></div><span class="btn btn-accent btn-sm">${t("tpl_all")} ›</span></a>
 <div class="mm-cols">${TPL_GROUPS.map(([g,ids])=>`<div class="mm-col"><p class="mm-g">${t(g)}</p>${ids.map(id=>`<a href="#/tpl/${id}" class="mm-item ${route==="tpl"&&curSub===id?"on":""}"><span class="mm-ico">${TPL_ICON[id]}</span><span class="mm-tx"><b>${esc(tplTx(id).n)}</b><small>${esc(tplTx(id).s)}</small></span></a>`).join("")}</div>`).join("")}</div></div></div></div>`}
function pageTemplates(){mkFonts();
 return `<section class="hero2 svc-hero"><div class="wrap" style="padding:64px 0 60px"><h1 style="max-width:22ch">${t("tpl_h")}</h1><p class="lead" style="max-width:62ch">${t("tpl_p")}</p><div class="cta-row"><a class="btn btn-accent btn-lg" href="#/templates#industries">${t("tpl_ind_h")}</a><a class="btn btn-ghost btn-lg" href="#/pricing">${t("nav_pricing")}</a>${waBtn("btn-lg")}</div></div></section>
 <div class="wrap" style="padding:64px 0 80px" id="industries"><h2 class="h2">${t("tpl_ind_h")}</h2><div class="tpl-grid">${TPL_IDS.map(id=>{const m=TPL_MOCKS[id][0],x=tplTx(id);return `<article class="tpl-card tpl-ind">${tplThumb(m,"tplgo").replace(`data-id="${m.id}"`,`data-id="${id}"`)}<div class="tpl-meta"><div><h3><a href="#/tpl/${id}">${esc(x.n)}</a></h3><p>${esc(x.s)}</p></div><span class="tpl-cnt">${t("tpl_n").replace("{n}",TPL_MOCKS[id].length)}</span></div><div class="tpl-act"><a class="btn btn-primary btn-sm" href="#/tpl/${id}">${t("tpl_view")} ›</a></div></article>`}).join("")}</div></div>
 ${tplSteps()}${tplFaq()}`}
function tplFaq(id){const Q=[...(id?[tplTx(id).q]:[]),[t("tpl_fq1q"),t("tpl_fq1a")],[t("tpl_fq2q"),t("tpl_fq2a")]];return `<section class="sec"><div class="wrap faq" style="max-width:860px;margin-inline:auto"><h2 class="h2">${t("tpl_faq")}</h2>${Q.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("")}</div></section>`}
function pageTpl(id){if(!TPL_MOCKS[id])return pageNotFound();mkFonts();const x=tplTx(id),pk=MK_IND[id].pkg;
 return `<section class="wrap phead tpl-head"><nav class="crumb" aria-label="Breadcrumb"><a href="#/">Penta</a> › <a href="#/templates">${t("nav_tpl")}</a> › <span>${esc(x.n)}</span></nav><h1>${esc(x.h)}</h1><p>${esc(x.p)}</p><div class="cta-row"><a class="btn btn-accent btn-lg" href="#/tpl/${id}#designs">${t("tpl_designs_h").replace("{n}",TPL_MOCKS[id].length)}</a><a class="btn btn-ghost btn-lg" href="#/pricing">${t("nav_pricing")}</a>${waBtn("btn-lg")}</div></section>
 <div class="wrap" id="designs" style="padding:8px 0 70px"><h2 class="h2">${esc(x.n)}: ${t("tpl_designs_h").replace("{n}",TPL_MOCKS[id].length)}</h2><div class="tpl-grid">${TPL_MOCKS[id].map(tplCard).join("")}</div><p class="note" style="margin-top:18px">${t("tpl_fict")}</p></div>
 <section class="sec tint"><div class="wrap tpl-why"><div><h2 class="h2">${t("tpl_why_h")}</h2><ul class="ticks">${x.f.map(f=>`<li>${esc(f)}</li>`).join("")}${[1,2,3,4].map(i=>`<li>${t("tpl_ch"+i)}</li>`).join("")}</ul></div>
 <aside class="incl"><h3>${t("tpl_rec")}: ${t("s_"+pk)}</h3>${QUOTE_PKG.has(pk)?propCard("#/proposal"):`<p class="note">${t("s_"+pk+"_d")}</p>${promoPrice(pk)}<h3 class="mi-sh">${MI_H[state.lang]||MI_H.en}</h3>${moIncList(pk)}<div class="cta-row"><a class="btn btn-accent" href="#/tpl/${id}#designs">${t("tpl_buy")}</a></div>`}</aside></div></section>
 ${tplSteps()}${tplFaq(id)}
 <div class="wrap mk-other" style="padding-bottom:60px"><span>${t("tpl_other")}:</span> ${TPL_IDS.filter(i=>i!==id).map(i=>`<a class="link" href="#/tpl/${i}">${esc(tplTx(i).n)}</a>`).join(" · ")}</div>`}
/* fit 1200px mockups into their frames */
function tplFit(root){(root||document).querySelectorAll(".tpl-sc").forEach(sc=>{const mk=sc.firstElementChild;if(!mk||!sc.clientWidth)return;const s=sc.clientWidth/1200;sc.dataset.s=s;mk.style.transform=`scale(${s})`})}
function tplHover(e){const b=e.target.closest&&e.target.closest(".tpl-thumb");if(!b||b.contains(e.relatedTarget))return;const sc=b.querySelector(".tpl-sc"),mk=sc&&sc.firstElementChild;if(!mk)return;const s=+sc.dataset.s||sc.clientWidth/1200,on=e.type==="mouseover",d=Math.max(0,mk.offsetHeight-sc.clientHeight/s);mk.style.transition=on?`transform ${Math.min(9,2+d/700)}s linear`:"transform .8s ease";mk.style.transform=`scale(${s}) translateY(${on?-d:0}px)`}
function tplDlg(){let d=$("#tplDlg");if(!d){d=document.createElement("dialog");d.id="tplDlg";d.className="tpl-dlg";document.body.appendChild(d);d.addEventListener("close",()=>{if(location.hash.startsWith("#design-"))safeReplaceState(null,"",location.pathname)});d.addEventListener("click",e=>{if(e.target===d)d.close()})}return d}
let TPL_CUR=null,TPL_TAB=0;
function tplView(m,i){const pg=(m.pages||MK_IND[m.ind].pages)[i];return `<div class="td-chrome"><span class="tpl-dots"><i></i><i></i><i></i></span>${m.live?`<a class="td-url" dir="ltr" href="${m.live}${i?pg[2]:""}" target="_blank" rel="noopener">${m.live.replace("https://","")}${i?pg[2]:""} ↗</a>`:`<span class="td-url" dir="ltr">preview.pentaservices.co.uk/${m.id}/${i?pg[1]+"/":""}</span>`}</div><div class="td-sc" id="tdSc"><div class="td-fit" id="tdFit">${mkPage(m,i)}</div></div>`}
function tplDlgHTML(m){const I=MK_IND[m.ind],x=tplTx(m.ind),pk=m.pkg,P=m.pages||I.pages,QP=QUOTE_PKG.has(pk);
 return `<div class="td-top"><div class="td-ttl"><b>${esc(m.n)}</b><small>${esc(x.n)} · ${t("st_"+m.v)}</small></div><div class="td-tabs" role="tablist">${P.map((p,i)=>`<button role="tab" aria-selected="${i===TPL_TAB}" data-action="tpltab" data-i="${i}">${esc(tplPgl(p[1]))}</button>`).join("")}</div><button class="td-x" data-action="tplclose" aria-label="${t("tpl_close")}">×</button></div>
 <div class="td-body"><div class="td-view" id="tdView">${tplView(m,TPL_TAB)}<p class="td-hint">${t("tpl_scroll")}</p></div>
 <aside class="td-info"><span class="td-pill">${m.live?t("tpl_livebadge"):t("tpl_concept")}</span><h2>${esc(m.n)}</h2><p class="td-for">${esc(t("tpl_for").replace("{x}",tplDesc(m)))}</p>
 <dl class="td-dl"><dt>${t("tpl_ind")}</dt><dd>${esc(x.n)}</dd><dt>${t("tpl_style")}</dt><dd>${t("st_"+m.v)}</dd><dt>${t("tpl_colors")}</dt><dd>${tplSw(m)}</dd><dt>${t("tpl_fonts")}</dt><dd>${MK_F[m.f[0]][0]}${m.f[0]!==m.f[1]?" · "+MK_F[m.f[1]][0]:""}</dd><dt>${t("tpl_time")}</dt><dd>${t("tpl_weeks").replace("{x}",TPL_WEEKS[pk]||"2–4")}</dd></dl>
 <h3>${t("tpl_pages")}</h3><ul class="ticks mi">${P.map(p=>`<li>${esc(tplPgl(p[1]))}</li>`).join("")}</ul>
 <h3>${t("tpl_feats")}</h3><ul class="ticks mi">${x.f.map(f=>`<li>${esc(f)}</li>`).join("")}</ul>
 <h3>${t("tpl_change_h")}</h3><ul class="ticks mi">${[1,2,3,4].map(i=>`<li>${t("tpl_ch"+i)}</li>`).join("")}</ul>
 <div class="td-buy"><p class="td-pk">${t("tpl_pkg")}: <b>${t("s_"+pk)}</b></p>${QP?`<div class="pp"><span class="pp-badge">${t("by_proposal")}</span><small>${t("quote_only_note")}</small></div>`:promoPrice(pk)+moIncDetails(pk)}${m.live?`<a class="btn btn-primary btn-lg" href="${m.live}" target="_blank" rel="noopener">${t("tpl_live")}</a>`:""}<button class="btn btn-accent btn-lg" data-action="tplbuy" data-id="${m.id}">${QP?t("tpl_req"):t("tpl_buy")}</button>${QP?"":`<button class="btn btn-ghost" data-action="tplask" data-id="${m.id}">${t("tpl_ask")}</button>`}<p class="note">${t("tpl_urg")}</p><p class="note">${t("tpl_fict")}</p></div></aside></div>`}
function tplFitView(){const sc=$("#tdSc"),fit=$("#tdFit");if(!sc||!fit||!fit.firstElementChild)return;const mk=fit.firstElementChild,s=Math.min(1,sc.clientWidth/1200);mk.style.transform=`scale(${s})`;fit.style.width=1200*s+"px";fit.style.height=mk.offsetHeight*s+"px"}
function tplOpen(id,tab){const m=TPL_BY[id];if(!m)return;mkFonts();TPL_CUR=m;TPL_TAB=tab||0;const d=tplDlg();d.innerHTML=tplDlgHTML(m);d.setAttribute("aria-label",m.n);fixLinks(d);if(!d.open)d.showModal();d.querySelector(".td-info").scrollTop=0;requestAnimationFrame(tplFitView);safeReplaceState(null,"",location.pathname+"#design-"+id)}
Object.assign(A,{
 ddT(el){["#dd","#ddS"].forEach(s=>{const x=$(s);if(x)x.classList.remove("open")});const d=$("#ddT");const o=d.classList.toggle("open");el.setAttribute("aria-expanded",o)},
 tplopen(el){tplOpen(el.dataset.id)},
 tplgo(el){go(routeToPath("tpl",el.dataset.id))},
 tpltab(el){if(!TPL_CUR)return;TPL_TAB=+el.dataset.i;document.querySelectorAll('#tplDlg [role="tab"]').forEach(b=>b.setAttribute("aria-selected",b===el));const v=$("#tdView");v.innerHTML=tplView(TPL_CUR,TPL_TAB)+`<p class="td-hint">${t("tpl_scroll")}</p>`;requestAnimationFrame(tplFitView)},
 tplclose(){const d=$("#tplDlg");if(d)d.close()},
 tplbuy(el){const m=TPL_BY[el.dataset.id];if(!m)return;if(QUOTE_PKG.has(m.pkg)){A.tplask(el);return}addSvc(m.pkg,true);state.tpl={id:m.id,n:m.n,ind:m.ind,pkg:m.pkg};LS.set("p_tpl",state.tpl);save();const d=$("#tplDlg");if(d&&d.open)d.close();toast(t("tpl_added").replace("{x}",m.n));go(routeToPath("cart"))},
 tplask(el){const m=TPL_BY[el.dataset.id];if(!m)return;if(QUOTE_PKG.has(m.pkg)){state.propSvc=m.pkg;state.quoteMsg=t("tpl_note").replace("{x}",m.n+" ("+tplTx(m.ind).n+")");const dq=$("#tplDlg");if(dq&&dq.open)dq.close();go(routeToPath("proposal"));return}state.quoteSvc=m.pkg;state.quoteMsg=t("tpl_note").replace("{x}",m.n+" ("+tplTx(m.ind).n+")");const d=$("#tplDlg");if(d&&d.open)d.close();go(routeToPath("contact"))},
 tplrm(){state.tpl=null;LS.set("p_tpl",null);rerenderKeepScroll()}});
addEventListener("resize",()=>{clearTimeout(tplFit.t);tplFit.t=setTimeout(()=>{tplFit(document);tplFitView()},120)});
document.addEventListener("mouseover",tplHover);document.addEventListener("mouseout",tplHover);
document.addEventListener("click",e=>{const d=$("#ddT");if(d&&d.classList.contains("open")&&!e.target.closest("#ddT"))d.classList.remove("open")});
addEventListener("keydown",e=>{if(e.key==="Escape"){const d=$("#ddT");if(d)d.classList.remove("open")}});
function tplAfterRender(){if(!$(".tpl-sc"))return;tplFit(document);const h=location.hash;if(h.startsWith("#design-")&&TPL_BY[h.slice(8)]&&!(($("#tplDlg")||{}).open))tplOpen(h.slice(8))}
function tplLd(id){const url=SITE+routeToPath("tpl",id),x=tplTx(id);return{"@context":"https://schema.org","@graph":[{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Penta Services","item":SITE+routeToPath("home")},{"@type":"ListItem","position":2,"name":t("nav_tpl"),"item":SITE+routeToPath("templates")},{"@type":"ListItem","position":3,"name":x.n,"item":url}]},{"@type":"CollectionPage","name":x.h,"description":x.sd,"url":url,"inLanguage":state.lang,"mainEntity":{"@type":"ItemList","itemListElement":TPL_MOCKS[id].map((m,i)=>({"@type":"ListItem","position":i+1,"name":m.n+" – "+tplDesc(m),"url":url+"#design-"+m.id}))}},{"@type":"FAQPage","mainEntity":[x.q,[t("tpl_fq1q"),t("tpl_fq1a")],[t("tpl_fq2q"),t("tpl_fq2a")]].map(([q,a])=>({"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}}))}]}}

state.tpl=LS.get("p_tpl",null);
/* ---------- Quote-only work (14 Oct 2026): mobile apps, cross-platform apps & PWAs, web apps & portals and API integrations
   are no longer sold as fixed packages. Visitors submit requirements; the team reviews them, asks questions and sends a proposal. ---------- */
const QUOTE_SVC=new Set(["app","pwa","saas","api"]); /* service pages */
const QUOTE_PKG=new Set(["app","saas"]);             /* catalogue ids that cannot be ordered online (also blocked on the server) */
const isQuote=id=>QUOTE_SVC.has(id)||QUOTE_PKG.has(id);
state.cart=state.cart.filter(i=>!(i.kind==="svc"&&QUOTE_PKG.has(i.id)));
Object.assign(FL,{plat:"Platforms",users:"Users",feat:"Key features and requirements",integ:"Systems to connect",links:"Links"});
Object.assign(I18N.en,{by_proposal:"Priced by proposal",quote_only_note:"Mobile apps, cross-platform apps and PWAs, web apps and portals, and API integrations are priced by proposal after we review your requirements.",req_btn:"Submit your requirements",prop_h:"Request a proposal",prop_p:"Tell us what you want to build. A project lead reviews your requirements, asks any follow-up questions and sends you a clear proposal with scope, timeline and price.",ps1h:"Share your requirements",ps1:"Describe your idea, who will use it, the key features and any systems it must connect to.",ps2h:"We review and ask questions",ps2:"A project lead studies your brief and follows up by email or a short call.",ps3h:"Receive your proposal",ps3:"A clear scope, timeline and fixed price for each phase, with no obligation.",custom_h:"Apps, portals and integrations",req_type:"What do you need?",req_platforms:"Platforms",req_users:"Who will use it? (customers, staff, partners…)",req_feat:"Key features and requirements",req_integr:"Systems to connect (CRM, ERP, payments…)",req_links:"Links to designs, documents or similar apps",req_other:"Something else / not sure yet",req_ok:"We'll review your requirements and reply within one business day, usually with a few questions or to arrange a short call.",tpl_req:"Request a proposal"});
Object.assign(I18N.it,{by_proposal:"Prezzo su proposta",quote_only_note:"App mobile, app multipiattaforma e PWA, web app e portali e integrazioni API hanno un prezzo su proposta, dopo l'analisi dei tuoi requisiti.",req_btn:"Invia i tuoi requisiti",prop_h:"Richiedi una proposta",prop_p:"Raccontaci cosa vuoi realizzare. Un project lead analizza i tuoi requisiti, ti fa eventuali domande e ti invia una proposta chiara con ambito, tempi e prezzo.",ps1h:"Condividi i requisiti",ps1:"Descrivi l'idea, chi la userà, le funzionalità principali e i sistemi da collegare.",ps2h:"Analizziamo e ti facciamo domande",ps2:"Un project lead studia il tuo brief e ti ricontatta via email o con una breve call.",ps3h:"Ricevi la proposta",ps3:"Ambito chiaro, tempi e prezzo fisso per ogni fase, senza impegno.",custom_h:"App, portali e integrazioni",req_type:"Di cosa hai bisogno?",req_platforms:"Piattaforme",req_users:"Chi la userà? (clienti, staff, partner…)",req_feat:"Funzionalità e requisiti principali",req_integr:"Sistemi da collegare (CRM, ERP, pagamenti…)",req_links:"Link a design, documenti o app simili",req_other:"Altro / non ancora sicuro",req_ok:"Analizzeremo i tuoi requisiti e risponderemo entro un giorno lavorativo, di solito con qualche domanda o per fissare una breve call.",tpl_req:"Richiedi una proposta"});
Object.assign(I18N.fr,{by_proposal:"Prix sur proposition",quote_only_note:"Les applications mobiles, applications multiplateformes et PWA, applications web et portails, ainsi que les intégrations API sont chiffrés sur proposition, après étude de vos besoins.",req_btn:"Envoyer vos besoins",prop_h:"Demander une proposition",prop_p:"Dites-nous ce que vous voulez créer. Un chef de projet étudie vos besoins, vous pose ses questions et vous envoie une proposition claire : périmètre, délais et prix.",ps1h:"Partagez vos besoins",ps1:"Décrivez votre idée, ses utilisateurs, les fonctionnalités clés et les systèmes à connecter.",ps2h:"Nous étudions et posons nos questions",ps2:"Un chef de projet analyse votre brief et revient vers vous par e-mail ou lors d'un court appel.",ps3h:"Recevez votre proposition",ps3:"Un périmètre clair, un calendrier et un prix fixe par phase, sans engagement.",custom_h:"Applications, portails et intégrations",req_type:"De quoi avez-vous besoin ?",req_platforms:"Plateformes",req_users:"Qui l'utilisera ? (clients, équipe, partenaires…)",req_feat:"Fonctionnalités et exigences principales",req_integr:"Systèmes à connecter (CRM, ERP, paiements…)",req_links:"Liens vers des maquettes, documents ou applis similaires",req_other:"Autre / pas encore sûr",req_ok:"Nous étudierons vos besoins et vous répondrons sous un jour ouvré, généralement avec quelques questions ou pour fixer un court appel.",tpl_req:"Demander une proposition"});
Object.assign(I18N.ar,{by_proposal:"السعر حسب العرض",quote_only_note:"تطبيقات الجوال والتطبيقات متعددة المنصات وPWA وتطبيقات الويب والبوابات وتكاملات API تُسعَّر بعرض مخصص بعد دراسة متطلباتك.",req_btn:"أرسل متطلباتك",prop_h:"اطلب عرض سعر",prop_p:"أخبرنا بما تريد بناءه. يدرس مدير المشروع متطلباتك، ويطرح عليك أي أسئلة، ثم يرسل إليك عرضًا واضحًا بالنطاق والجدول الزمني والسعر.",ps1h:"شارك متطلباتك",ps1:"صف فكرتك ومن سيستخدمها والميزات الرئيسية والأنظمة التي يجب ربطها.",ps2h:"ندرسها ونطرح الأسئلة",ps2:"يدرس مدير المشروع طلبك ويتواصل معك عبر البريد الإلكتروني أو مكالمة قصيرة.",ps3h:"استلم عرضك",ps3:"نطاق واضح وجدول زمني وسعر ثابت لكل مرحلة، دون أي التزام.",custom_h:"التطبيقات والبوابات والتكاملات",req_type:"ما الذي تحتاجه؟",req_platforms:"المنصات",req_users:"من سيستخدمه؟ (العملاء، الموظفون، الشركاء…)",req_feat:"الميزات والمتطلبات الرئيسية",req_integr:"الأنظمة المطلوب ربطها (CRM، ERP، المدفوعات…)",req_links:"روابط لتصاميم أو مستندات أو تطبيقات مشابهة",req_other:"أمر آخر / لست متأكدًا بعد",req_ok:"سندرس متطلباتك ونرد خلال يوم عمل واحد، عادةً ببعض الأسئلة أو لترتيب مكالمة قصيرة.",tpl_req:"اطلب عرض سعر"});
Object.assign(I18N.zh,{by_proposal:"按方案报价",quote_only_note:"移动应用、跨平台应用与 PWA、Web 应用与门户以及 API 集成，均在评估您的需求后按方案报价。",req_btn:"提交您的需求",prop_h:"申请项目方案",prop_p:"告诉我们您想做什么。项目经理会评估您的需求、提出必要的问题，并向您发送包含范围、周期和价格的清晰方案。",ps1h:"提交需求",ps1:"描述您的想法、使用人群、核心功能以及需要对接的系统。",ps2h:"评估并沟通",ps2:"项目经理研究您的需求，并通过邮件或简短通话与您沟通。",ps3h:"收到方案",ps3:"清晰的范围、时间表和每个阶段的固定价格，无任何义务。",custom_h:"应用、门户与集成",req_type:"您需要什么？",req_platforms:"平台",req_users:"谁会使用？（客户、员工、合作伙伴…）",req_feat:"核心功能与需求",req_integr:"需要对接的系统（CRM、ERP、支付…）",req_links:"设计稿、文档或类似应用的链接",req_other:"其他 / 暂不确定",req_ok:"我们会评估您的需求，并在一个工作日内回复，通常会提几个问题或约一次简短通话。",tpl_req:"申请项目方案"});
