function propSteps(){return `<ol class="psteps">${[1,2,3].map(i=>`<li><b>${t("ps"+i+"h")}</b><span>${t("ps"+i)}</span></li>`).join("")}</ol>`}
function propMini(){return `<div class="pp"><span class="pp-badge">${t("by_proposal")}</span><small>${t("ps1h")} → ${t("ps2h")} → ${t("ps3h")}</small></div>`}
function propCard(href){return `<p class="note">${t("quote_only_note")}</p>${propSteps()}<div class="cta-row"><a class="btn btn-accent" href="${href||"#/proposal"}" ${href==="#quote"?'data-action="goquote"':""}>${t("req_btn")}</a></div>`}
function quoteList(){return `<div class="cq-list">${["app","pwa","saas","api"].map(id=>`<a href="#/service/${id}">${SICON[id]}<span>${t("sp_"+id)}</span></a>`).join("")}</div>`}
function reqFields(msg){return `<fieldset class="reqf"><legend>${t("req_platforms")}</legend><div class="cr">${["iOS","Android","Web"].map(p=>`<label><input type="checkbox" name="pl_${p}"><span>${p}</span></label>`).join("")}</div></fieldset>
 <label>${t("req_feat")}<textarea class="inp" name="feat" required>${esc(msg||"")}</textarea></label>
 <div class="two"><label>${t("req_users")}<input class="inp" name="users"></label><label>${t("req_integr")}<input class="inp" name="integ"></label></div>
 <label>${t("req_links")}<input class="inp" name="links" dir="ltr" placeholder="https://"></label>`}
function pageProposal(){SS={id:"proposal",opts:[],extras:[],tech:[]};const sv=state.propSvc||"app",msg=state.quoteMsg||"";state.quoteMsg="";
 return `<section class="hero2 svc-hero"><div class="wrap" style="padding:64px 0 56px"><h1 style="max-width:20ch">${t("prop_h")}</h1><p class="lead" style="max-width:62ch">${t("prop_p")}</p></div></section>
 <div class="wrap prop-grid"><div><h2 class="h2" style="font-size:1.5rem">${t("tpl_steps_h")}</h2>${propSteps()}${quoteList()}<div class="callout" style="margin-top:24px">${t("quote_only_note")}</div></div>
 <div class="fcard" id="quoteBox"><form class="form" data-form="quote" style="max-width:none">
  <label>${t("req_type")}<select class="inp" name="svc">${["app","pwa","saas","api","other"].map(id=>`<option value="${id}" ${id===sv?"selected":""}>${id==="other"?t("req_other"):t("sp_"+id)}</option>`).join("")}</select></label>
  ${reqFields(msg)}
  <div class="two"><label>${t("name")}<input class="inp" name="n" required autocomplete="name" value="${esc(state.user?state.user.name:"")}"></label><label>${t("email")}<input class="inp" type="email" name="e" required dir="ltr" autocomplete="email" value="${esc(state.user?state.user.email:"")}"></label></div>
  <div class="two"><label>${t("c_company")}<input class="inp" name="c" autocomplete="organization"></label><label>${t("phone_wa")}<input class="inp" name="p" type="tel" dir="ltr" autocomplete="tel"></label></div>
  <div class="two"><label>${t("c_country")}<input class="inp" name="co" autocomplete="country-name"></label><label>${t("timeline")}<select class="inp" name="tl">${[1,2,3,4].map(i=>`<option>${t("tl"+i)}</option>`).join("")}</select></label></div>
  <label>${t("c_budget")}<select class="inp" name="b">${["< £5,000","£5,000–10,000","£10,000–25,000","£25,000–50,000","£50,000+",t("req_other")].map(x=>`<option>${x}</option>`).join("")}</select></label>
  <button class="btn btn-accent btn-lg" type="submit">${t("req_btn")}</button></form></div></div>`}

