const WB_GRACE=7;
const wbAppUrl=(path)=>`${WB_APP}${state.lang==="ar"?"/ar":""}${path||"/dashboard"}`;

/* the monthly-fee details shown on pricing rows, cart lines and package cards */
{const _moInc=moInc;moInc=function(id){if(isWb(id)){const s=SVC[id];return s&&s.mo?((WB_INC[state.lang]||WB_INC.en)[id]||WB_INC.en[id]):[]}return _moInc(id)}}

/* one Website Builder package per order (choosing another replaces it); packages never count towards bundle discounts */
{const _addSvc=addSvc;addSvc=function(id,silent){if(isWb(id)&&state.cart.some(i=>i.kind==="svc"&&isWb(i.id)&&i.id!==id)){state.cart=state.cart.filter(i=>!(i.kind==="svc"&&isWb(i.id)));if(!silent)toast(t("wb_one"))}return _addSvc(id,silent)}}
{const _totals=totals;totals=function(items,billing){items=items||state.cart;const wb=items.filter(i=>i.kind==="svc"&&isWb(i.id));if(!wb.length)return _totals(items,billing);
 const T=_totals(items.filter(i=>!(i.kind==="svc"&&isWb(i.id))),billing);const mo=wb.reduce((a,i)=>a+SVC[i.id].mo*(i.qty||1),0),period=mo*T.mult;
 return{...T,mo:T.mo+mo,moNet:T.moNet+mo,period:T.period+period,due:T.due+period}}}

function wbPlanCard(id,i){const s=SVC[id],[ws,pp]=WB_LIMITS[id],ann=state.billing==="annual";
 return `<article class="pkg ${i===1?"hot":""}" data-testid="wb-plan-${id}">${i===1?`<span class="badge">${t("popular")}</span>`:""}<span class="tier">${t("wb_limits").replace("{s}",ws).replace("{p}",pp)}</span><h3>${t("s_"+id)}</h3><p class="for">${t("s_"+id+"_d")}</p><ul>${moInc(id).map(x=>`<li>${esc(x)}</li>`).join("")}</ul><p class="from"><b>${money(s.mo*(ann?10:1))}${ann?t("per_year"):t("per_month")}</b>${t("trust_2")}</p><button class="btn ${i===1?"btn-accent":"btn-primary"}" data-action="wbadd" data-id="${id}">${inCart(id)?"✓ "+t("added"):t("add_to_cart")}</button></article>`}
function pageWebBuilder(){const steps=[1,2,3],feats=[1,2,3,4,5,6],faqs=[1,2,3,4];
 return `<section class="wrap phead" style="padding-bottom:28px"><span class="pp-badge">${t("wb_badge")}</span><h1>${t("wb_h")}</h1><p>${t("wb_p")}</p>
  <div class="cta-row"><a class="btn btn-accent btn-lg" href="${wbAppUrl()}" data-testid="wb-start">${t("wb_start")} ›</a><a class="btn btn-ghost btn-lg" href="#plans">${t("wb_see")}</a></div><p class="note">${t("wb_free_note")}</p></section>
 <section class="wrap" style="padding-bottom:40px"><h2>${t("wb_how_h")}</h2><div class="plans">${steps.map(n=>`<article class="pkg"><span class="tier">${n}</span><h3>${t("wb_s"+n+"h")}</h3><p class="for">${t("wb_s"+n)}</p></article>`).join("")}</div></section>
 <section class="wrap" style="padding-bottom:40px"><h2>${t("wb_feat_h")}</h2><div class="plans">${feats.map(n=>`<article class="pkg"><h3>${t("wb_f"+n+"h")}</h3><p class="for">${t("wb_f"+n)}</p></article>`).join("")}</div></section>
 <section class="wrap" id="plans" style="padding-bottom:40px"><h2>${t("wb_plans_h")}</h2><p class="note">${t("wb_plans_p")}</p>${billingSeg()}
  <div class="plans" style="margin-top:18px;grid-template-columns:repeat(auto-fit,minmax(230px,1fr))"><article class="pkg" data-testid="wb-plan-free"><span class="tier">${t("wb_limits").replace("{s}",1).replace("{p}",3)}</span><h3>${t("wb_free")}</h3><p class="for">${t("wb_free_d")}</p><ul>${t("wb_free_inc").split("|").map(x=>`<li>${esc(x)}</li>`).join("")}</ul><p class="from"><b>${money(0)}</b></p><a class="btn btn-ghost" href="${wbAppUrl()}">${t("wb_free_btn")}</a></article>${WB_IDS.map(wbPlanCard).join("")}</div></section>
 <section class="wrap" style="padding-bottom:90px"><h2>${t("wb_faq_h")}</h2>${faqs.map(n=>`<details class="mi-d" style="margin:10px 0"><summary><b>${t("wb_q"+n)}</b></summary><p>${t("wb_a"+n).replace("{g}",WB_GRACE)}</p></details>`).join("")}</section>`}
