/* Single sign-on: /api/sso/authorize sends signed-out visitors to /<lang>/account/#sso=<authorize url>.
   Once they are signed in with a verified email, carry on to the app. */
{const h=location.hash;if(h.startsWith("#sso=")){const next=decodeURIComponent(h.slice(5));safeReplaceState(null,"",location.pathname+location.search);
 if(/^\/api\/sso\/authorize\?/.test(next)){try{sessionStorage.setItem("p_sso",next)}catch(e){}setTimeout(()=>toast(t("wb_sso_note")),80)}}}
function ssoContinue(){let next=null;try{next=sessionStorage.getItem("p_sso")}catch(e){}if(!next||!state.user||!state.user.verified)return;try{sessionStorage.removeItem("p_sso")}catch(e){}location.assign(next)}
{const _render=render;render=function(){const r=_render();ssoContinue();return r}}

/* deep link from the builder's plan page: /<lang>/cart/?add=wbb&billing=annual */
{const q=new URLSearchParams(location.search);const add=q.get("add");if(add&&isWb(add)){if(q.get("billing")==="annual"||q.get("billing")==="monthly"){state.billing=q.get("billing")}addSvc(add,true);save();safeReplaceState(null,"",location.pathname)}}

