function checkPk(){if(navigator.webdriver)return;let tz="";try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||""}catch(e){}
 fetch("/api/geo.php?tz="+encodeURIComponent(tz),{cache:"no-store"}).then(r=>r.json()).then(j=>{
  if(j.country==="PK"&&j.pkr){PB.PKR=j.pkr.pb;BENCH.PKR=j.pkr.bench;PK_OK=true;if(!LS.get("p_cur_set",0)||LS.get("p_cur",null)==="PKR")state.cur="PKR";save();rerenderKeepScroll()}
  else if(LS.get("p_cur",null)==="PKR")save()}).catch(()=>{})}
